// Datapack index: which ids a pack defines (recipes, loot tables, functions, tags...) and the tag contents that
// matter for conflicts (replace + values). Pure over a list of (path, reader). Bounded; tolerant of junk JSON.
import type { DatapackFile, DatapackIndex, DatapackTag } from "./types";

export const DATAPACK_LIMITS = { maxFiles: 5000, maxTagFiles: 2000, maxJsonBytes: 256 * 1024 };

// Folder names became singular in 1.21; older packs (and some current ones) still use the plural.
const SINGULAR: Record<string, string> = {
  functions: "function", loot_tables: "loot_table", recipes: "recipe", advancements: "advancement", predicates: "predicate", item_modifiers: "item_modifier", structures: "structure",
  items: "item", blocks: "block", entity_types: "entity_type", fluids: "fluid", game_events: "game_event",
};
const sing = (s: string) => SINGULAR[s] ?? s;

export type PackFileRef = { path: string; read: () => Promise<Buffer | null> | Buffer | null };

/** `data/<ns>/<type>/<id path>.<ext>` -> { type, id } (null for anything else). */
export function classifyDataPath(p: string): DatapackFile | null {
  const m = /^data\/([a-z0-9_.-]+)\/(.+)\.(json|mcfunction|nbt)$/.exec(p);
  if (!m) return null;
  const [, ns, rest] = m;
  const segs = rest.split("/");
  if (segs.length < 2) return null;
  let typeSegs = 1;
  if (segs[0] === "tags" || segs[0] === "worldgen") typeSegs = segs[0] === "tags" && segs[1] === "worldgen" ? 3 : 2;
  if (segs.length <= typeSegs) return null;
  const type = segs.slice(0, typeSegs).map(sing).join("/");
  return { type, id: `${ns}:${segs.slice(typeSegs).join("/")}` };
}

function parseJson(buf: Buffer | null): unknown {
  if (!buf || buf.length > DATAPACK_LIMITS.maxJsonBytes) return undefined;
  try { return JSON.parse(buf.toString("utf8").replace(/^﻿/, "")); } catch { return undefined; }
}

export function readPackMcmeta(buf: Buffer | null): DatapackIndex["format"] {
  const j = parseJson(buf) as { pack?: Record<string, unknown> } | undefined;
  const p = j && typeof j === "object" ? j.pack : undefined;
  if (!p || typeof p !== "object") return null;
  const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) ? v : Array.isArray(v) && typeof v[0] === "number" ? v[0] : null);
  const desc = typeof p.description === "string" ? p.description : p.description != null ? JSON.stringify(p.description).slice(0, 200) : null;
  return { packFormat: num(p.pack_format), min: num(p.min_format), max: num(p.max_format), description: desc };
}

export function tagValues(j: unknown): { replace: boolean; values: string[] } | null {
  if (!j || typeof j !== "object" || Array.isArray(j)) return null;
  const o = j as { replace?: unknown; values?: unknown };
  if (!Array.isArray(o.values)) return null;
  const values = o.values.map((v) => (typeof v === "string" ? v : v && typeof v === "object" && typeof (v as { id?: unknown }).id === "string" ? (v as { id: string }).id : null)).filter((v): v is string => !!v);
  return { replace: o.replace === true, values };
}

export async function indexDatapack(name: string, source: DatapackIndex["source"], container: DatapackIndex["container"], files: PackFileRef[], mcmeta: Buffer | null): Promise<DatapackIndex> {
  const idx: DatapackIndex = { name, source, container, format: readPackMcmeta(mcmeta), files: [], tags: [], issues: [] };
  if (!idx.format) idx.issues.push("pack.mcmeta missing or invalid (Minecraft will not load this pack)");
  let tagFiles = 0;
  const sorted = [...files].sort((a, b) => (a.path < b.path ? -1 : 1));
  if (sorted.length > DATAPACK_LIMITS.maxFiles) idx.issues.push(`only the first ${DATAPACK_LIMITS.maxFiles} of ${sorted.length} files were indexed`);
  for (const f of sorted.slice(0, DATAPACK_LIMITS.maxFiles)) {
    const c = classifyDataPath(f.path);
    if (!c) continue;
    idx.files.push(c);
    if (c.type.startsWith("tags/") && f.path.endsWith(".json")) {
      if (++tagFiles > DATAPACK_LIMITS.maxTagFiles) continue;
      const t = tagValues(parseJson(await f.read()));
      if (!t) { idx.issues.push(`${f.path}: unreadable tag`); continue; }
      idx.tags.push({ registry: c.type.slice(5), id: c.id, replace: t.replace, values: t.values } satisfies DatapackTag);
    }
  }
  if (tagFiles > DATAPACK_LIMITS.maxTagFiles) idx.issues.push(`only ${DATAPACK_LIMITS.maxTagFiles} tag files were read`);
  return idx;
}

