// Given a ModSpec (and optionally the raw prompt) and the game's adapter, decide which artifact routes the mod
// needs, which of them Cyrus can build today, and the honest limits the user must see before tokens are spent.
// With a plan, the asset tier gate runs here first and DOWNGRADES (strips gated custom assets with a reason)
// instead of failing. Game-agnostic: all game facts are the adapter's route rules and version capabilities.
import type { GameAdapter, RouteRule } from "../adapters/types";
import { ARTIFACT_ROUTES, type ArtifactRoute, type ModSpec } from "./spec";
import { canAsset, downgradeSpecAssets, type AssetDenial } from "./asset-gate";

export type RouteLimit = { id: string; severity: "info" | "warn" | "block"; message: string };

export type RouteDecision = {
  game: string;
  version: string;
  /** Every route the mod needs, in canonical order. */
  routes: ArtifactRoute[];
  /** Subsets of `routes` by what the adapter can do today. */
  available: ArtifactRoute[];
  planned: ArtifactRoute[];
  unsupported: ArtifactRoute[];
  /** "plugin", "plugin+resourcePack", "dataPack", ... or "clientMod-unsupported" when nothing buildable is left. */
  label: string;
  /** True when every needed route is available today and nothing blocks the target version. */
  buildableNow: boolean;
  limits: RouteLimit[];
  matchedRules: string[];
  /** The spec after the plan downgrade (unchanged when no plan was given). */
  spec: ModSpec;
  removedAssets: AssetDenial[];
};

export type RouteOptions = {
  prompt?: string;
  /** Pass to apply the asset tier gate. `{ plan: undefined }` = unknown plan, so asset creation fails closed. */
  gate?: { plan: unknown };
};

const order = (s: Set<ArtifactRoute>) => ARTIFACT_ROUTES.filter((r) => s.has(r));

/** The text routing reads. Non-goals and constraints are left out on purpose ("no custom blocks" must not trigger). */
function routingText(spec: ModSpec, prompt?: string): string {
  return [spec.summary, ...spec.requirements.map((r) => r.text), ...spec.assets.map((a) => a.purpose), prompt ?? ""].join("\n").toLowerCase();
}

const compiled = new WeakMap<RouteRule, RegExp[]>();
function keywordHit(rule: RouteRule, text: string): boolean {
  let res = compiled.get(rule);
  if (!res) { res = rule.keywords.map((k) => new RegExp(k, "i")); compiled.set(rule, res); }
  return res.some((re) => re.test(text));
}

export function routeSpec(input: ModSpec, adapter: GameAdapter, opts: RouteOptions = {}): RouteDecision {
  const limits: RouteLimit[] = [];
  const matchedRules: string[] = [];
  let spec = input;
  let removedAssets: AssetDenial[] = [];
  if (opts.gate) {
    const d = downgradeSpecAssets(input, opts.gate.plan);
    spec = d.spec;
    removedAssets = d.removed;
    d.removed.forEach((r, i) => limits.push({ id: `asset_gate:${r.assetId}`, severity: "warn", message: d.notices[i] }));
  }
  const version = spec.target.version;
  const text = routingText(spec, opts.prompt);
  const kinds = new Set(spec.assets.map((a) => a.kind));
  const need = new Set<ArtifactRoute>(spec.routes);

  for (const rule of adapter.routeRules) {
    const byAsset = !!rule.assetKinds?.some((k) => kinds.has(k));
    if (!byAsset && !keywordHit(rule, text)) continue;
    matchedRules.push(rule.id);
    // Asked for in words only, for asset kinds this plan may not create: say so, do not add the route.
    if (!byAsset && opts.gate && rule.assetKinds?.length && rule.assetKinds.every((k) => !canAsset(opts.gate!.plan, k, "create").ok)) {
      const d = canAsset(opts.gate.plan, rule.assetKinds[0], "create");
      if (!d.ok) limits.push({ id: `${rule.id}:plan`, severity: "warn", message: d.reason });
      continue;
    }
    if (rule.route) need.add(rule.route);
    if (rule.limit) limits.push({ id: rule.id, severity: rule.limit.severity, message: rule.limit.message });
    if (rule.requiresCapability && !adapter.versions.hasCapability(version, rule.requiresCapability.capability)) {
