  const planned = routes.filter((r) => avail(r) === "planned");
  const unsupported = routes.filter((r) => avail(r) === "unsupported");
  for (const r of [...planned, ...unsupported]) {
    const a = adapter.artifacts.find((x) => x.route === r);
    limits.push({ id: `route:${r}`, severity: "warn", message: a?.note ?? `${adapter.name} cannot use the ${r} route.` });
  }
