  const label = live.length ? live.join("+") : unsupported.includes("clientMod") ? "clientMod-unsupported" : "unsupported";
  const buildableNow = live.length > 0 && planned.length === 0 && unsupported.length === 0 && !limits.some((l) => l.severity === "block");
  return { game: adapter.game, version, routes, available, planned, unsupported, label, buildableNow, limits, matchedRules, spec, removedAssets };
