export type RouteIntent = "create" | "refine" | "fix" | "explain" | "install" | "browse" | "unknown";

export type RouteDecision = {
// Cyrus R1 asset slice: which custom assets a BUILD may generate (pure, client-safe).
// The build request names what the user wants (an explicit `assets` list from the composer, words in the prompt that
// the adapter's route rules recognise, or textures the mod already has); the plan-tier gate
// (lib/cyrus/engine-core/asset-gate.ts) decides what the plan may create or edit; the version registry decides what
// the target version can show; ASSET_PIPELINE_READY says which pipelines exist. Anything refused is a DOWNGRADE: the
// plugin is still built, without that asset, with a plain reason for the user. Never trust the client for any of it:
// the server calls planBuildAssets on every request (lib/cyrus/assets/request.ts).
import { getAdapter } from "../adapters";
import { canAsset, normalizePlan, PLAN_LABEL, type AssetPlan } from "../engine-core/asset-gate";
import { hasCapability, resourcePackFormat } from "../versions/registry";

import { BUILD_ASSET_KINDS, type BuildAssetKind } from "./kinds";
export { BUILD_ASSET_KINDS, isBuildAssetKind, type BuildAssetKind } from "./kinds";

/**
 * Which generation pipelines the build path can run today. Both slices are built (R1): the service writes texture
 * and sound specs, lib/cyrus/assets/sync.ts renders them (sounds on the render host, see docs "Cyrus sound slice (R1)").
 * The plan gate is unchanged: sound = Saka and the top plan, textures = the top plan, free/Katara none.
 */
export const ASSET_PIPELINE_READY: Readonly<Record<BuildAssetKind, boolean>> = { texture: true, sound: true };

export type AllowedAssets = Record<BuildAssetKind, boolean>;
export type AssetDecisionCode = "allowed" | "asset_locked" | "plan_unknown" | "version" | "not_ready";
export type BuildAssetDecision = { kind: BuildAssetKind; code: AssetDecisionCode; reason?: string; needs?: AssetPlan };
export type BuildAssetPlan = {
  /** What the request asked for (sorted, unique). Empty = no asset path at all (the pre-R1 behaviour). */
  requested: BuildAssetKind[];
  allowed: AllowedAssets;
  decisions: BuildAssetDecision[];
  /** Customer-visible, one per refused kind: why, and what Cyrus builds instead. */
  notices: string[];
  plan: AssetPlan | null;
};

const FALLBACK: Record<BuildAssetKind, string> = { texture: "vanilla item looks", sound: "vanilla sounds" };
const WORD: Record<BuildAssetKind, string> = { texture: "Custom textures", sound: "Custom sounds" };

/** Asset kinds the adapter's route rules recognise in the request text (deterministic keyword match, no AI). */
export function detectAssetKinds(text: string, game = "minecraft"): BuildAssetKind[] {
  const adapter = getAdapter(game);
  if (!adapter || !text) return [];
  const out = new Set<BuildAssetKind>();
  for (const rule of adapter.routeRules) {
    if (!rule.assetKinds?.length) continue;
    if (!rule.keywords.some((k) => new RegExp(k, "i").test(text))) continue;
    for (const k of rule.assetKinds) {
      if (k === "sound") out.add("sound");
      else if (k === "texture" || k === "model") out.add("texture"); // item models are drawn with the texture pipeline
    }
  }
  return BUILD_ASSET_KINDS.filter((k) => out.has(k));
}

/** The request's own list: `assets: ["texture"]` or `assets: { texture: true }` (anything else is ignored). */
export function explicitAssetKinds(raw: unknown): BuildAssetKind[] {
  if (Array.isArray(raw)) return BUILD_ASSET_KINDS.filter((k) => raw.includes(k));
  if (raw && typeof raw === "object") return BUILD_ASSET_KINDS.filter((k) => (raw as Record<string, unknown>)[k] === true);
  return [];
}

export function requestedAssetKinds(input: { explicit?: unknown; text?: string; existing?: BuildAssetKind[]; game?: string }): BuildAssetKind[] {
  const s = new Set<BuildAssetKind>([...explicitAssetKinds(input.explicit), ...detectAssetKinds(input.text ?? "", input.game), ...(input.existing ?? [])]);
  return BUILD_ASSET_KINDS.filter((k) => s.has(k));
}

/** Can the target version show this kind at all? Textures need 1.21.4+ item model definitions and a known pack format. */
function versionReason(kind: BuildAssetKind, mcVersion: string): string | null {
  const pf = resourcePackFormat(mcVersion, { needsItemModels: kind === "texture" });
  if (kind === "texture" && !hasCapability(mcVersion, "itemModelDefinitions")) {
    return `${WORD.texture} need Minecraft 1.21.4 or newer (item model definitions) and this mod targets ${mcVersion}, so Cyrus builds it with ${FALLBACK.texture}. Pick 1.21.4 or newer to get custom textures.`;
  }
  if (!pf.ok) return `${WORD[kind]} aren't available for Minecraft ${mcVersion} yet (${pf.error}), so Cyrus builds it with ${FALLBACK[kind]}.`;
  return null;
}

/**
 * Decide, per requested kind: plan gate first (create for a new mod, edit for a change), then the version, then
 * whether the pipeline exists. `plan` is whatever the token economy says (`all`, `yakko`, `saka`, ...); unknown or
 * missing -> nothing may be created (fail closed).
 */
export function planBuildAssets(input: { plan: unknown; requested: BuildAssetKind[]; mcVersion: string; change?: boolean; existing?: BuildAssetKind[] }): BuildAssetPlan {
  const plan = normalizePlan(input.plan);
  const allowed: AllowedAssets = { texture: false, sound: false };
  const decisions: BuildAssetDecision[] = [];
  const notices: string[] = [];
  for (const kind of BUILD_ASSET_KINDS.filter((k) => input.requested.includes(k))) {
    const g = canAsset(plan, kind, input.change ? "edit" : "create");
    if (!g.ok) {
      const code = g.code === "plan_unknown" ? "plan_unknown" : "asset_locked";
      // Keeping what the mod already has is never gated: say so instead of implying the textures disappear.
      const reason = input.existing?.includes(kind)
        ? `This mod's existing ${WORD[kind].toLowerCase()} are kept exactly as they are. ${g.reason}`
        : `${g.reason} Cyrus will build the plugin with ${FALLBACK[kind]} instead.`;
      decisions.push({ kind, code, reason, ...(g.needs ? { needs: g.needs } : {}) });
      notices.push(reason);
      continue;
    }
    const vr = versionReason(kind, input.mcVersion);
    if (vr) { decisions.push({ kind, code: "version", reason: vr }); notices.push(vr); continue; }
    if (!ASSET_PIPELINE_READY[kind]) {
      const reason = `${WORD[kind]} are not built into Cyrus yet, so this mod uses ${FALLBACK[kind]} for now.`;
      decisions.push({ kind, code: "not_ready", reason });
      notices.push(reason);
      continue;
    }
    allowed[kind] = true;
    decisions.push({ kind, code: "allowed" });
  }
  return { requested: [...input.requested].sort() as BuildAssetKind[], allowed, decisions, notices, plan };
}

export const anyAllowed = (a: AllowedAssets) => BUILD_ASSET_KINDS.some((k) => a[k]);
export const planLabel = (p: AssetPlan | null) => (p ? PLAN_LABEL[p] : "unknown");
// Asset kinds a Cyrus build can generate (R1: texture now, sound next). Tiny and dependency-free so client code
// (lib/cyrus/meta.ts) can use it without pulling in the adapters or the version registry.
export const BUILD_ASSET_KINDS = ["texture", "sound"] as const;
export type BuildAssetKind = (typeof BUILD_ASSET_KINDS)[number];
export const isBuildAssetKind = (v: unknown): v is BuildAssetKind => typeof v === "string" && (BUILD_ASSET_KINDS as readonly string[]).includes(v);

// Cyrus R1: the asset part of a build request, decided ON THE SERVER (lib/modbuilder/create.ts calls this after the
// token gate passed). Reads the real plan (lib/cyrus/tokens tierOf), runs the gate, and for an allowed asset kind
// creates/loads the mod's CyrusProject so the build has its reserved nx_ namespace. Dependencies are injectable so
// the gate wiring is unit-tested for every plan without a database (test/cyrus-assets.test.ts).
//
// Byte-identical rule: when nothing is requested, nothing is looked up, no project is created and `service` is null,
// so the build service request is exactly the pre-R1 one. When something is requested but refused, `service` is
// still null (the service sees no assets) and the refusal is only recorded for the user (`meta.notices`).
import type { BuildAssetKind, BuildAssetPlan } from "./plan";
import { anyAllowed, BUILD_ASSET_KINDS, planBuildAssets, requestedAssetKinds } from "./plan";

/** The build service's `assets` field (services/modbuilder/textures.js parseAssetsRequest). */
export type SvcAssets = { texture: boolean; sound: boolean; namespace: string; library?: boolean };

/** What ModBuild.cyrus.assets records about the request (lib/cyrus/meta.ts). */
export type CyrusAssetMeta = { requested: BuildAssetKind[]; allowed: BuildAssetKind[]; notices: string[]; projectId?: string; namespace?: string };

export type ProjectRef = { id: string; namespace: string };
export type AssetRequestDeps = {
  /** The account's plan tier (token economy). Throwing = unknown = fail closed. */
  tierOf: (userId: string) => Promise<string>;
  projectForRootBuild: (rootBuildId: string) => Promise<ProjectRef | null>;
  createProject: (input: { userId: string; game: string; rootBuildId: string; title?: string | null }) => Promise<ProjectRef>;
  /** Sound slice: may customer builds use the owner's sound library (licence confirmed)? Default: CYRUS_SOUND_LIBRARY_CLEARED=1. */
  soundLibraryCleared?: () => boolean;
};

export type AssetRequestInput = {
  userId: string;
  /** The chain root: the new build's own id for a fresh build, base.rootBuildId ?? base.id for a change. */
  rootBuildId: string;
  change: boolean;
  /** body.assets from the client: a REQUEST only, never a permission. */
  explicit?: unknown;
  /** The prompt (fresh) or the change request (change). */
  text: string;
  mcVersion: string;
  /** Asset kinds the mod already has (the base build's stored result), so a change can keep editing them. */
  existing?: BuildAssetKind[];
  title?: string | null;
};

export type AssetRequestResult = { plan: BuildAssetPlan | null; service: SvcAssets | null; meta: CyrusAssetMeta | null };

const NONE: AssetRequestResult = { plan: null, service: null, meta: null };

export async function resolveBuildAssets(input: AssetRequestInput, deps: AssetRequestDeps): Promise<AssetRequestResult> {
  const requested = requestedAssetKinds({ explicit: input.explicit, text: input.text, existing: input.existing });
  if (!requested.length) return NONE;
  let tier: unknown = null;
  try { tier = await deps.tierOf(input.userId); } catch { tier = null; } // unknown token state: fail closed
  const plan = planBuildAssets({ plan: tier, requested, mcVersion: input.mcVersion, change: input.change, existing: input.existing });
  const meta: CyrusAssetMeta = { requested, allowed: BUILD_ASSET_KINDS.filter((k) => plan.allowed[k]), notices: [...plan.notices] };
  if (!anyAllowed(plan.allowed)) return { plan, service: null, meta };
  let project: ProjectRef | null = null;
  try {
    project = (await deps.projectForRootBuild(input.rootBuildId)) ?? (await deps.createProject({ userId: input.userId, game: "minecraft", rootBuildId: input.rootBuildId, title: input.title ?? null }));
  } catch {
    // A racing create (root_taken) means it exists now; anything else: no namespace, so no assets (fail closed).
    project = await deps.projectForRootBuild(input.rootBuildId).catch(() => null);
  }
  if (!project) {
    const msg = "Cyrus couldn't set up this mod's asset project right now, so it builds the plugin without custom assets. Try again later.";
    return { plan: { ...plan, allowed: { texture: false, sound: false } }, service: null, meta: { ...meta, allowed: [], notices: [...meta.notices, msg] } };
  }
  return {
    plan,
    // `library` only rides along with sound, so texture-only requests stay byte-identical to the texture slice
    service: { texture: plan.allowed.texture, sound: plan.allowed.sound, namespace: project.namespace, ...(plan.allowed.sound ? { library: (deps.soundLibraryCleared ?? (() => process.env.CYRUS_SOUND_LIBRARY_CLEARED === "1"))() } : {}) },
    meta: { ...meta, projectId: project.id, namespace: project.namespace },
  };
}

/** Asset kinds a stored build result already carries (ModBuild.result.assets, written by lib/cyrus/assets/sync.ts). */
export function existingAssetKinds(result: unknown): BuildAssetKind[] {
  const a = (result as { assets?: { textures?: unknown[]; sounds?: unknown[] } } | null)?.assets;
  return [
    ...(Array.isArray(a?.textures) && a!.textures!.length ? (["texture"] as const) : []),
    ...(Array.isArray(a?.sounds) && a!.sounds!.length ? (["sound"] as const) : []),
  ];
}
