  let names = [];
  try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  return names.filter((e) => e.isFile()).map((e) => `${SOUND_DIR}/${e.name}`).filter((rel) => SOUND_FILE_RE.test(rel)).sort()
