    if (foreign.length) soft.push(`The plugin uses the namespace ${foreign.join(", ")}; this mod's reserved namespace is ${namespace}. Every custom sound key is "${namespace}:<set>.<event>".`);
    if (/"minecraft:[a-z0-9_.]+"/.test(text) && /playSound/.test(text) && /"minecraft:(entity|block|item|ambient)\./.test(text)) soft.push(`The plugin plays a "minecraft:" sound key. Custom sounds must use "${namespace}:<set>.<event>" keys; never override vanilla sounds.`);
