use ::java::util::text::Text
use ::java::util::InclusiveRange

struct Pack {
	pack: struct PackBase {
		description: Text,
		/// Optional since 1.21.9. Define it if you want older versions to recognize your pack with
		/// a “made for a newer version” warning message.
		/// 
		/// Because of backwards compatibility, only the main pack format can
		/// be used here. Minor formats can only be specified in min and max format.
		pack_format?: #[pack_format] int,
		/// Must not be specified in case min_format indicates a format version for 1.21.9 and
		/// later.
		#[since="1.20.2"]
		supported_formats?: InclusiveRange<#[pack_format] int>,
		/// The minimun format that is supported. To specify a minor version, use a list of two
		/// integers.
		#[since="1.21.9"]
		min_format?: #[pack_format] PackFormat,
		/// The maximum format that is supported. To specify a minor version, use a list of two
		/// integers.
		#[since="1.21.9"]
		max_format?: #[pack_format] PackFormat,
	},
	#[since="1.19"]
	filter?: PackFilter,
	#[since="1.19.3"]
	features?: PackFeatures,
	#[since="1.20.2"]
	overlays?: PackOverlays,
}

struct PackFilter {
	block: [BlockPattern],
}

struct BlockPattern {
	namespace?: #[regex_pattern] string,
	path?: #[regex_pattern] string,
}

struct PackFeatures {
	enabled: [#[id] FeatureFlag],
}

enum(string) FeatureFlag {
	Vanilla = "vanilla",
	#[until="1.20"] Update120 = "update_1_20",
	#[until="1.21.2"] Bundle = "bundle",
	#[since="1.20.2"] TradeRebalance = "trade_rebalance",
	#[since="1.20.3"] #[until="1.21"] Update121 = "update_1_21",
	#[since="1.21.2"] RedstoneExperiments = "redstone_experiments",
	#[since="1.21.2"] MinecartImprovements = "minecart_improvements",
	#[since="1.21.2"] #[until="1.21.4"] WinterDrop = "winter_drop",
}

struct PackOverlays {
	entries: [PackOverlay],
}

struct PackOverlay {
	directory: string @ 1..,
	formats?: InclusiveRange<#[pack_format] int>,
	min_format?: #[pack_format] PackFormat,
	max_format?: #[pack_format] PackFormat,
}

type PackFormat = (int | [int] @ 1 | [int, int @ 0..])
