// A MemberPlacer that places Mod Pack members through Nxeon's shared Mods engine (lib/mods/engine.ts), so the
// engine's state file records every jar/datapack the pack put on the server (the Mods tab and later engine runs then
// know these files are Nxeon's). Same imports as lib/cyrus/managed/installer.ts already uses (no new Nxeon coupling).
// The unit installer (./install.ts) snapshots the engine's state.json with everything else, so a failed pack install
// also undoes the engine's bookkeeping. OFF unless CYRUS_MODPACK_INSTALL_REAL=1; off, the unit refuses before
// touching the server. Must run where the engine runs (the worker, under its per-server lock). Not wired anywhere yet.
import { installOrUpdate, uninstall, STATE_PATH } from "../../mods/engine";
import { minecraftInstaller } from "../../mods/installers/minecraft";
import type { CatalogFacts, FamilyInstaller, Resolution, ServerFacts } from "../../mods/types";
import type { GuestFs } from "../../mods/guest-fs";
import { FetchError } from "../../mods/safe-fetch";
import type { MemberPlacer, PlacedFile } from "./install";

export const MODPACK_SOURCE = "cyrus-modpack";
export const MODPACK_REAL_FLAG = "CYRUS_MODPACK_INSTALL_REAL";
const noNetwork = async (): Promise<never> => { throw new FetchError("Mod Pack members never download inside the engine (fetched and verified first)", "host"); };

const facts = (packId: string, memberId: string, label: string): CatalogFacts => ({
  id: `modpack:${packId}:${memberId}`, gameFamily: "minecraft", slug: `${packId}-${memberId}`, name: label, source: MODPACK_SOURCE, sourceId: `${packId}:${memberId}`,
  url: null, category: "library", appliesToVariant: null, loaders: ["paper", "purpur"], gameVersions: [], serverSide: "required",
});

function resolution(packId: string, memberId: string, label: string, version: string, f: PlacedFile): Resolution {
  const filename = f.target.slice(f.target.lastIndexOf("/") + 1);
  return {
    packages: [{
      key: `${MODPACK_SOURCE}:${packId}:${memberId}`, name: label, version, versionId: `${packId}:${version}`,
      file: { url: `modpack://${packId}/${memberId}/${filename}`, filename, size: f.data.length, hashes: { sha256: f.sha256 } },
      placement: f.role === "datapack" ? "datapack" : "plugin-jar", requires: [], incompatible: [], prefetched: f.data, root: true,
    }],
    notes: [],
  };
}

export function engineMemberPlacer(deps: { fs: GuestFs; server: ServerFacts; packId: string; env?: Record<string, string | undefined> }): MemberPlacer {
  const env = deps.env ?? process.env;
  const off = env[MODPACK_REAL_FLAG] !== "1";
  const fam = (r: Resolution): FamilyInstaller => ({ ...minecraftInstaller, sources: [MODPACK_SOURCE], resolve: async () => r, legacyPaths: () => [] });
  return {
    statePaths: [STATE_PATH],
    ...(off ? { disabledReason: `Mod Pack installs through the Mods engine are switched off (${MODPACK_REAL_FLAG} is not 1); nothing was changed` } : {}),
    async place({ member, files }) {
      if (off) throw new Error("switched off");
      const primary = files.filter((f) => f.role !== "config");
      if (primary.length !== 1) throw new Error(`${member.id}: expected exactly one jar or datapack, got ${primary.length}`);
      const r = await installOrUpdate(fam(resolution(deps.packId, member.id, member.label, member.version, primary[0])), facts(deps.packId, member.id, member.label), deps.server, { fs: deps.fs, fetcher: noNetwork }, "update");
      if (!r.ok) throw new Error(r.error);
      const placedAt = r.fileName;
      if (placedAt && !primary[0].target.endsWith(`/${placedAt}`)) throw new Error(`${member.id}: the engine placed ${placedAt}, expected ${primary[0].target}`);
      for (const c of files.filter((f) => f.role === "config")) { const part = `${c.target}.nxeon-part`; await deps.fs.writeFile(part, c.data); await deps.fs.rename(part, c.target); }
    },
    async remove({ memberId, targets }) {
      if (off) throw new Error("switched off");
      const stub = resolution(deps.packId, memberId, memberId, "0", { target: "/x", data: Buffer.alloc(0), sha256: "0".repeat(64), role: "plugin" });
      const r = await uninstall(fam(stub), facts(deps.packId, memberId, memberId), deps.server, { fs: deps.fs, fetcher: noNetwork });
      if (!r.ok) throw new Error(r.error);
      for (const t of targets) if (await deps.fs.stat(t)) await deps.fs.remove(t); // config files (the engine removes only what it placed)
    },
  };
}
