// Cyrus data pack studio: the SAFETY validator for .mcfunction files (pure, deterministic, no game parsing).
//
// Why it exists: data pack functions run as the server (permission level `function-permission-level`, 2 by default and
// up to 4 on some hosts), from #minecraft:load / #minecraft:tick, without any player. A generated function must never
// be able to take over or break a customer's server. So every command is checked against an ALLOWLIST of command
// roots (everything else is refused, including plugin commands such as /lp), `execute ... run <cmd>` chains are
// unwrapped and checked to the end, the call graph (function, schedule, execute if function, function tags) must be
// acyclic and shallow, and size / loop limits apply. Fail closed: anything the checker cannot read is refused.
//
// Each finding is { severity: "error" | "warn", rule, at, message }. Errors block the pack, warnings are shown.

export const FN_LIMITS = {
  maxFunctions: 64,
  maxCommandsPerFunction: 256,
  maxCommandsTotal: 2048,
  maxLineLength: 2000,
  maxBytesTotal: 256 * 1024,
  /** Longest call chain (A calls B calls C ... ), counted in functions. */
  maxCallDepth: 8,
  /** Commands in a function that runs every tick (and everything it calls). */
  maxTickCommands: 64,
  maxScheduleCommands: 16,
  /** Shortest delay a `schedule function` may use, in ticks (20 = 1 s). */
  minScheduleTicks: 1,
  maxForceloadAdds: 4,
  maxExecuteDepth: 12,
} as const;

/** Command roots a function may use. Everything not listed is refused. */
export const ALLOWED_COMMANDS: readonly string[] = [
  "advancement", "attribute", "bossbar", "clear", "clone", "damage", "data", "dialog", "effect", "enchant", "execute", "experience", "xp",
  "fill", "fillbiome", "forceload", "function", "gamemode", "gamerule", "give", "item", "kill", "list", "locate", "loot", "me", "msg", "tell", "w",
  "particle", "place", "playsound", "random", "recipe", "return", "ride", "rotate", "say", "schedule", "scoreboard", "setblock", "spawnpoint",
  "spectate", "spreadplayers", "stopsound", "summon", "swing", "tag", "team", "teammsg", "tm", "teleport", "tp", "tellraw", "time", "title",
  "trigger", "waypoint", "weather", "worldborder", "stopwatch",
];

/** Why the most important refused roots are refused (shown to the model and the user). */
export const DENIED_COMMANDS: Readonly<Record<string, string>> = {
  op: "gives a player operator rights", deop: "removes operator rights", ban: "bans players", "ban-ip": "bans addresses", banlist: "reads the ban list",
  pardon: "unbans players", "pardon-ip": "unbans addresses", kick: "kicks players", whitelist: "changes who may join", stop: "stops the server",
  "save-off": "turns world saving off", "save-on": "changes world saving", "save-all": "forces a full world save", reload: "reloads every data pack (lag, loops)",
  publish: "opens the world to LAN", unpublish: "changes LAN publishing", transfer: "sends players to another server", difficulty: "changes a server setting",
  defaultgamemode: "changes a server setting", setidletimeout: "changes a server setting", setworldspawn: "moves the world spawn", seed: "reveals the world seed",
  tick: "freezes or speeds up the whole server", debug: "starts profiling", jfr: "starts a Java Flight Recorder dump", perf: "starts profiling",
  test: "runs GameTests", fetchprofile: "makes network requests", datapack: "enables or disables data packs", version: "is not needed in a data pack",
};

/** Items a function may never hand out or place: they run arbitrary commands or edit the world freely. */
export const OP_ITEMS = ["command_block", "chain_command_block", "repeating_command_block", "command_block_minecart", "structure_block", "structure_void", "jigsaw", "debug_stick", "test_block", "test_instance_block"];

/** Gamerules a function may change (both the pre-1.21.11 camelCase and the 1.21.11+ snake_case names). Others are server policy. */
export const SAFE_GAMERULES = [
  "keepInventory", "keep_inventory", "doDaylightCycle", "advance_time", "doWeatherCycle", "advance_weather", "doMobSpawning", "spawn_mobs", "mobGriefing", "mob_griefing",
  "doFireTick", "fire_spread_radius_around_player", "naturalRegeneration", "natural_health_regeneration", "showDeathMessages", "show_death_messages",
  "announceAdvancements", "show_advancement_messages", "doImmediateRespawn", "immediate_respawn", "playersSleepingPercentage", "players_sleeping_percentage",
  "fallDamage", "fall_damage", "fireDamage", "fire_damage", "drowningDamage", "drowning_damage", "freezeDamage", "freeze_damage", "doInsomnia", "spawn_phantoms",
  "doPatrolSpawning", "spawn_patrols", "doTraderSpawning", "spawn_wandering_traders", "disableRaids", "raids", "doMobLoot", "mob_drops", "doTileDrops", "block_drops",
  "doEntityDrops", "entity_drops", "pvp",
];

export type FnFinding = { severity: "error" | "warn"; rule: string; at: string; message: string };
export type FnInput = { id: string; commands: string[]; runOn?: "load" | "tick" };
export type FnContext = {
  namespace: string;
  /** Command roots that exist in the target version (from the real command tree); absent = do not check. */
  versionCommands?: ReadonlySet<string>;
  /** Gamerule names that exist in the target version; absent = do not check. */
  versionGamerules?: ReadonlySet<string>;
  /** Function tags of this pack: "#ns:path" -> function ids (own functions only). */
  functionTags?: ReadonlyMap<string, string[]>;
  /** Extra entry points that run every tick / on load (from tag resources on #minecraft:tick / #minecraft:load). */
  tickFunctions?: readonly string[];
  loadFunctions?: readonly string[];
};

/** Split one command line into top-level tokens (quotes and [] {} () kept together). null = unbalanced (unreadable). */
export function tokenize(line: string): string[] | null {
  const out: string[] = [];
  let cur = "", depth = 0, quote: string | null = null;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quote) {
      cur += c;
      if (c === "\\" && i + 1 < line.length) { cur += line[++i]; continue; }
      if (c === quote) quote = null;
      continue;
    }
    if (c === '"' || c === "'") { quote = c; cur += c; continue; }
    if (c === "[" || c === "{" || c === "(") depth++;
    if (c === "]" || c === "}" || c === ")") { depth--; if (depth < 0) return null; }
    if (c === " " && depth === 0) { if (cur) out.push(cur); cur = ""; continue; }
    cur += c;
  }
  if (quote || depth !== 0) return null;
  if (cur) out.push(cur);
  return out;
}

const ID_RE = /^#?[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const bareItem = (tok: string) => tok.replace(/^minecraft:/, "").replace(/[[{].*$/, "");

type Walk = { calls: { target: string; via: string; schedule?: boolean }[]; commands: number; summons: number; forceloadAdds: number; schedules: { target: string; append: boolean }[] };

/** Check ONE command (already without a leading slash). Pushes findings; returns the walk facts. */
function checkCommand(raw: string, at: string, ctx: FnContext, f: FnFinding[], w: Walk, depth = 0): void {
  const err = (rule: string, message: string) => f.push({ severity: "error", rule, at, message });
  const warn = (rule: string, message: string) => f.push({ severity: "warn", rule, at, message });
  if (depth > FN_LIMITS.maxExecuteDepth) return err("execute_depth", `execute is nested more than ${FN_LIMITS.maxExecuteDepth} levels deep`);
  const t = tokenize(raw);
  if (!t || !t.length) return err("unreadable", "the command could not be read (unbalanced quotes or brackets)");
  const root = t[0].toLowerCase();
  if (root.includes(":")) return err("namespaced_root", `"${t[0]}" is a namespaced command; functions may only use vanilla commands (plugin commands are refused)`);
  if (DENIED_COMMANDS[root]) return err("denied_command", `"${root}" is not allowed in a data pack function: it ${DENIED_COMMANDS[root]}`);
  if (!ALLOWED_COMMANDS.includes(root)) return err("not_allowlisted", `"${root}" is not on Nxeon's allowlist of data pack commands`);
  if (ctx.versionCommands && !ctx.versionCommands.has(root)) return err("unknown_command", `"${root}" is not a command in this Minecraft version`);
  if (/run_command/i.test(raw)) return err("click_command", "text with a run_command click action is refused (a click would run a command with the sign's or book's rights)");
  if (/\bCommand\s*:/.test(raw)) return err("command_nbt", "NBT that sets a Command (command blocks / minecarts) is refused");
