  w.commands++;

  switch (root) {
    case "execute": {
      for (let i = 1; i < t.length; i++) {
        const tok = t[i];
        if (tok === "run") {
          const rest = t.slice(i + 1).join(" ");
          if (!rest) return err("execute_run", "execute ... run needs a command after run");
          return checkCommand(rest, at, ctx, f, w, depth + 1);
        }
        if ((tok === "if" || tok === "unless") && t[i + 1] === "function" && t[i + 2]) { w.calls.push({ target: t[i + 2], via: "execute if function" }); i += 2; }
        if (ctx.versionCommands && /^[a-z]+$/.test(tok) && i === 1) {
          // first sub-command must exist (cheap sanity check; the real server parses the rest)
          /* handled by the real load test */
        }
      }
      return; // execute without run (pure condition) is fine
    }
    case "return": {
      const i = t.indexOf("run");
      if (i > 0) return checkCommand(t.slice(i + 1).join(" "), at, ctx, f, w, depth + 1);
      return;
    }
    case "function": {
      if (!t[1]) return err("function_target", "function needs a function id");
      if (t.length > 2) return err("macro_call", "function calls with arguments (macros: `with` / {args}) are refused: they build commands at run time that cannot be checked");
      w.calls.push({ target: t[1], via: "function" });
      return;
    }
    case "schedule": {
      if (t[1] === "clear") { if (t[2]) w.calls.push({ target: t[2], via: "schedule clear", schedule: true }); return; }
      if (t[1] !== "function" || !t[2] || !t[3]) return err("schedule_form", "use `schedule function <id> <time> [replace]` or `schedule clear <id>`");
      const m = /^(\d+(?:\.\d+)?)([tsd]?)$/.exec(t[3]);
      if (!m) return err("schedule_time", `schedule time "${t[3]}" must be a number of ticks (t), seconds (s) or days (d)`);
      const ticks = Number(m[1]) * (m[2] === "s" ? 20 : m[2] === "d" ? 24000 : 1);
      if (ticks < FN_LIMITS.minScheduleTicks) return err("schedule_time", `schedule delay must be at least ${FN_LIMITS.minScheduleTicks} tick`);
      w.schedules.push({ target: t[2], append: t[4] === "append" });
      w.calls.push({ target: t[2], via: "schedule", schedule: true });
      return;
    }
    case "forceload": {
      if (t[1] === "add") {
        if (t.length > 4) return err("forceload_range", "forceload add may load one chunk per command (no ranges)");
        w.forceloadAdds++;
      }
      return;
    }
    case "gamerule": {
      const rule = (t[1] ?? "").replace(/^minecraft:/, "");
      if (!rule) return err("gamerule", "gamerule needs a rule name");
      if (ctx.versionGamerules && !ctx.versionGamerules.has(rule) && !ctx.versionGamerules.has(`minecraft:${rule}`)) return err("unknown_gamerule", `gamerule "${rule}" does not exist in this Minecraft version`);
      if (!SAFE_GAMERULES.includes(rule)) return err("gamerule_policy", `gamerule "${rule}" is server policy and may not be changed by a data pack`);
      if (!t[2]) warn("gamerule_read", `gamerule ${rule} without a value only reads it`);
      return;
    }
    case "gamemode": {
      if (/^(creative|1)$/.test(t[1] ?? "")) return err("gamemode_creative", "a data pack may not put players into creative mode");
      return;
    }
    case "kill": {
      const sel = t[1] ?? "@s";
      if (/^@e(\[|$)/.test(sel) && !/type=|tag=|limit=|name=|team=/.test(sel)) return err("kill_all", "`kill @e` without a type, tag, team, name or limit filter would also kill every player");
