}

/** Resolve "#ns:tag" or "ns:id" to own function ids; foreign targets are reported. */
function targetsOf(target: string, ctx: FnContext, f: FnFinding[], at: string): string[] {
  if (target.startsWith("#")) {
    const list = ctx.functionTags?.get(target);
    if (!list) { f.push({ severity: "error", rule: "call_target", at, message: `${target} is not a function tag of this pack` }); return []; }
    return list;
  }
  if (!ID_RE.test(target)) { f.push({ severity: "error", rule: "call_target", at, message: `"${target}" is not a function id` }); return []; }
  if (!target.startsWith(`${ctx.namespace}:`)) { f.push({ severity: "error", rule: "call_target", at, message: `"${target}" is outside this pack's namespace ${ctx.namespace}; functions may only call their own functions` }); return []; }
  return [target];
}

export type FnReport = { findings: FnFinding[]; functions: number; commands: number; bytes: number; maxDepth: number; tickCommands: number };

/** Check every function of a pack together (call graph, budgets) and each command on its own. */
export function checkFunctions(fns: FnInput[], ctx: FnContext): FnReport {
  const f: FnFinding[] = [];
  const ids = new Set(fns.map((x) => `${ctx.namespace}:${x.id}`));
  const edges = new Map<string, string[]>();
  let total = 0, bytes = 0, scheduleCount = 0, forceloads = 0;
  const perFn = new Map<string, number>();
  if (fns.length > FN_LIMITS.maxFunctions) f.push({ severity: "error", rule: "too_many_functions", at: "functions", message: `${fns.length} functions; the limit is ${FN_LIMITS.maxFunctions}` });
  for (const fn of fns) {
    const full = `${ctx.namespace}:${fn.id}`;
    const w: Walk = { calls: [], commands: 0, summons: 0, forceloadAdds: 0, schedules: [] };
    let count = 0;
    fn.commands.forEach((rawLine, i) => {
      const at = `${full} line ${i + 1}`;
      bytes += Buffer.byteLength(rawLine) + 1;
      if (rawLine.length > FN_LIMITS.maxLineLength) { f.push({ severity: "error", rule: "line_length", at, message: `line is longer than ${FN_LIMITS.maxLineLength} characters` }); return; }
      if (/[\r\n\u0000]/.test(rawLine)) { f.push({ severity: "error", rule: "line_break", at, message: "one command per entry: no line breaks or NUL characters" }); return; }
      const line = rawLine.trim();
      if (!line || line.startsWith("#")) return;
      if (line.startsWith("$")) { f.push({ severity: "error", rule: "macro_line", at, message: "macro lines ($...) are refused: they build commands at run time that cannot be checked" }); return; }
      if (line.startsWith("/")) { f.push({ severity: "error", rule: "leading_slash", at, message: "function commands have no leading /" }); return; }
      count++;
      checkCommand(line, at, ctx, f, w);
    });
    total += count;
    perFn.set(full, count);
    if (count > FN_LIMITS.maxCommandsPerFunction) f.push({ severity: "error", rule: "function_size", at: full, message: `${count} commands; the limit per function is ${FN_LIMITS.maxCommandsPerFunction}` });
    scheduleCount += w.schedules.length;
    forceloads += w.forceloadAdds;
    const targets: string[] = [];
    for (const c of w.calls) for (const tgt of targetsOf(c.target, ctx, f, full)) {
      if (!ids.has(tgt)) f.push({ severity: "error", rule: "call_target", at: full, message: `${c.via} ${tgt}: no such function in this pack` });
      else if (!c.schedule) targets.push(tgt);
      else if (c.via === "schedule" && w.schedules.find((s) => s.target === c.target)?.append && (fn.runOn === "tick" || (ctx.tickFunctions ?? []).includes(full))) {
        f.push({ severity: "error", rule: "schedule_append_tick", at: full, message: "schedule ... append from a tick function piles up a new run every tick" });
      }
    }
    edges.set(full, [...new Set(targets)]);
    if (fn.runOn === "tick" && w.summons) f.push({ severity: "warn", rule: "tick_summon", at: full, message: "summons an entity from a tick function: make sure a condition limits it, or it spawns 20 per second" });
  }
  if (total > FN_LIMITS.maxCommandsTotal) f.push({ severity: "error", rule: "pack_size", at: "functions", message: `${total} commands in total; the limit is ${FN_LIMITS.maxCommandsTotal}` });
  if (bytes > FN_LIMITS.maxBytesTotal) f.push({ severity: "error", rule: "pack_size", at: "functions", message: `function text is ${bytes} bytes; the limit is ${FN_LIMITS.maxBytesTotal}` });
  if (scheduleCount > FN_LIMITS.maxScheduleCommands) f.push({ severity: "error", rule: "schedule_count", at: "functions", message: `${scheduleCount} schedule commands; the limit is ${FN_LIMITS.maxScheduleCommands}` });
  if (forceloads > FN_LIMITS.maxForceloadAdds) f.push({ severity: "error", rule: "forceload_count", at: "functions", message: `${forceloads} forceload add commands; the limit is ${FN_LIMITS.maxForceloadAdds} chunks per pack` });

  // call graph: no recursion (direct calls; schedules are delayed so they are not recursion), bounded depth
  let maxDepth = 0;
  const state = new Map<string, number>(); // 1 = on stack, 2 = done
  const depthOf = new Map<string, number>();
  const visit = (n: string, stack: string[]): number => {
    if (state.get(n) === 1) { f.push({ severity: "error", rule: "recursion", at: n, message: `function recursion: ${[...stack.slice(stack.indexOf(n)), n].join(" -> ")}` }); return 0; }
    if (state.get(n) === 2) return depthOf.get(n) ?? 1;
    state.set(n, 1);
    let d = 1;
    for (const m of edges.get(n) ?? []) d = Math.max(d, 1 + visit(m, [...stack, n]));
    state.set(n, 2); depthOf.set(n, d);
    return d;
  };
  for (const n of [...edges.keys()].sort()) maxDepth = Math.max(maxDepth, visit(n, []));
  if (maxDepth > FN_LIMITS.maxCallDepth) f.push({ severity: "error", rule: "call_depth", at: "functions", message: `call chains are ${maxDepth} functions deep; the limit is ${FN_LIMITS.maxCallDepth}` });

  // tick budget: everything reachable (by direct calls) from a tick function
  const tickRoots = [...new Set([...fns.filter((x) => x.runOn === "tick").map((x) => `${ctx.namespace}:${x.id}`), ...(ctx.tickFunctions ?? [])])].filter((x) => ids.has(x));
  const reach = new Set<string>();
  const walk = (n: string) => { if (reach.has(n)) return; reach.add(n); for (const m of edges.get(n) ?? []) walk(m); };
  tickRoots.forEach(walk);
  const tickCommands = [...reach].reduce((s, n) => s + (perFn.get(n) ?? 0), 0);
  if (tickCommands > FN_LIMITS.maxTickCommands) f.push({ severity: "error", rule: "tick_budget", at: "functions", message: `${tickCommands} commands run every tick; the limit is ${FN_LIMITS.maxTickCommands} (use schedule or a counter for slower work)` });
  return { findings: f, functions: fns.length, commands: total, bytes, maxDepth, tickCommands };
}

