// DataPackSpec v1 (Cyrus R2 data pack studio): the typed, VERSION-NEUTRAL description of a data pack that the build
// model writes (assets/datapack/<name>.json), the studio edits and the per-version emitters (./emit) turn into real
// Minecraft JSON. The AI never writes version-specific JSON: field names, ingredient shapes, text encodings and
// pack.mcmeta are the emitters' job. Zod types here; `dataPackJsonSchema()` is the portable contract
// (datapack.v1.schema.json, regenerate with `npx tsx scripts/cyrus-datapack-schema.ts`; a test fails while stale).
//
// Identifiers: every resource lives in the project's reserved namespace (`nx_<8>`, engine-core identifiers); a
// resource's `id` is only the path ("chests/ruby_vault"). References are full ids: own ones (`nx_x:path`) must exist
// in the spec, vanilla ones (`minecraft:...`, `#minecraft:...`) must exist in the TARGET version's real registry data
// (./versions.ts). Validation never throws: { ok, spec | errors, warnings, report } like ModSpec.
import { z } from "zod";
import { NAMESPACE_RE, buildIdentifier } from "../engine-core/identifiers";
import { checkFunctions, type FnFinding } from "./functions";
import { dataPackFeatures, firstVersionWith, isVanilla, vanillaIds, type DataPackFeatures, type IdKind } from "./versions";

export const DATAPACK_SPEC_VERSION = 1;
export const DATAPACK_LIMITS = { maxResources: 128, maxSpecBytes: 256 * 1024, maxFiles: 4, maxPackBytes: 1024 * 1024 } as const;

const PATH = /^[a-z0-9_]+(\/[a-z0-9_]+){0,5}$/;
const REF = /^#?[a-z0-9_.-]+:[a-z0-9_./-]+$/;
const Path = z.string().max(64).regex(PATH, "lowercase letters, digits, _ and / (max 6 segments)");
const RecipePath = z.string().regex(/^[a-z0-9_]{1,48}$/, "lowercase letters, digits, _ (max 48)");
const Ref = z.string().max(120).regex(REF, "a namespaced id like minecraft:diamond or #minecraft:planks");
const Int = (min: number, max: number) => z.number().int().min(min).max(max);

export const TEXT_COLORS = ["black", "dark_blue", "dark_green", "dark_aqua", "dark_red", "dark_purple", "gold", "gray", "dark_gray", "blue", "green", "aqua", "red", "light_purple", "yellow", "white"] as const;
/** Text: a plain string or one styled run. Emitted as a text component (JSON object, or a JSON string where the version needs it). */
export const TextSchema = z.union([
  z.string().min(1).max(200),
  z.strictObject({
    text: z.string().min(1).max(200),
    color: z.union([z.enum(TEXT_COLORS), z.string().regex(/^#[0-9a-fA-F]{6}$/)]).optional(),
    bold: z.boolean().optional(), italic: z.boolean().optional(), underlined: z.boolean().optional(), strikethrough: z.boolean().optional(),
  }),
]);
export type DpText = z.infer<typeof TextSchema>;

/** A number, a uniform range { min, max } or a binomial { n, p }. */
export const NumSchema = z.union([z.number().min(-1000).max(1000), z.strictObject({ min: z.number().min(-1000).max(1000), max: z.number().min(-1000).max(1000) }), z.strictObject({ n: Int(0, 100), p: z.number().min(0).max(1) })]);
export type DpNum = z.infer<typeof NumSchema>;

/** An ingredient: an item id, an item tag (#...), or a list of alternatives. */
export const IngredientSchema = z.union([Ref, z.array(Ref).min(1).max(16)]);
export type DpIngredient = z.infer<typeof IngredientSchema>;

export const ResultSchema = z.strictObject({
  item: Ref, count: Int(1, 99).optional(),
  /** Shown instead of the item's normal name (minecraft:item_name; not italic). Not on cooking results. */
  name: TextSchema.optional(),
  lore: z.array(TextSchema).max(8).optional(),
});
export type DpResult = z.infer<typeof ResultSchema>;

const CraftCategory = z.enum(["building", "redstone", "equipment", "misc"]);
const CookCategory = z.enum(["food", "blocks", "misc"]);
const Group = z.string().regex(/^[a-z0-9_]{1,32}$/);
export const RecipeSchema = z.discriminatedUnion("kind", [
  z.strictObject({ kind: z.literal("shaped"), pattern: z.array(z.string().min(1).max(3)).min(1).max(3), key: z.record(z.string().regex(/^[^ ]$/, "one character (not space)"), IngredientSchema), result: ResultSchema, category: CraftCategory.optional(), group: Group.optional() }),
  z.strictObject({ kind: z.literal("shapeless"), ingredients: z.array(IngredientSchema).min(1).max(9), result: ResultSchema, category: CraftCategory.optional(), group: Group.optional() }),
  z.strictObject({ kind: z.enum(["smelting", "blasting", "smoking", "campfire_cooking"]), ingredient: IngredientSchema, result: ResultSchema, experience: z.number().min(0).max(100).optional(), cookingTime: Int(1, 32767).optional(), category: CookCategory.optional(), group: Group.optional() }),
  z.strictObject({ kind: z.literal("stonecutting"), ingredient: IngredientSchema, result: ResultSchema }),
  z.strictObject({ kind: z.literal("smithing_transform"), template: IngredientSchema, base: IngredientSchema, addition: IngredientSchema, result: ResultSchema }),
]);
export type DpRecipe = z.infer<typeof RecipeSchema>;

export const LootConditionSchema = z.discriminatedUnion("cond", [
  z.strictObject({ cond: z.literal("random_chance"), chance: z.number().min(0).max(1) }),
  z.strictObject({ cond: z.literal("killed_by_player") }),
  z.strictObject({ cond: z.literal("survives_explosion") }),
  /** The tool used (block loot) is one of these items / in this tag. */
  z.strictObject({ cond: z.literal("match_tool"), items: z.union([Ref, z.array(Ref).min(1).max(16)]) }),
  z.strictObject({ cond: z.literal("weather"), raining: z.boolean().optional(), thundering: z.boolean().optional() }),
]);
export type DpCondition = z.infer<typeof LootConditionSchema>;
const Conds = z.array(LootConditionSchema).max(8).optional();
const EnchantOptions = z.union([Ref, z.array(Ref).min(1).max(32)]);
export const LootFunctionSchema = z.discriminatedUnion("fn", [
  z.strictObject({ fn: z.literal("set_count"), count: NumSchema, add: z.boolean().optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_damage"), damage: NumSchema, conditions: Conds }),
  z.strictObject({ fn: z.literal("enchant_randomly"), options: EnchantOptions.optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("enchant_with_levels"), levels: NumSchema, options: EnchantOptions.optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_name"), name: TextSchema, target: z.enum(["custom_name", "item_name"]).optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_lore"), lore: z.array(TextSchema).min(1).max(8), mode: z.enum(["append", "replace_all"]).optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("set_enchantments"), enchantments: z.record(Ref, Int(1, 255)), add: z.boolean().optional(), conditions: Conds }),
  z.strictObject({ fn: z.literal("explosion_decay"), conditions: Conds }),
  z.strictObject({ fn: z.literal("furnace_smelt"), conditions: Conds }),
  /** Extra items per Looting level (vanilla enchanted_count_increase with minecraft:looting). */
  z.strictObject({ fn: z.literal("looting_bonus"), count: NumSchema, conditions: Conds }),
]);
export type DpFunction = z.infer<typeof LootFunctionSchema>;
const Fns = z.array(LootFunctionSchema).max(12).optional();
const Weight = { weight: Int(1, 1000).optional(), quality: Int(-100, 100).optional() };
export const LootEntrySchema = z.discriminatedUnion("kind", [
  z.strictObject({ kind: z.literal("item"), item: Ref, ...Weight, conditions: Conds, functions: Fns }),
  /** expand true: pick ONE item of the tag (each with the entry's weight); false (default): drop every item of the tag. */
  z.strictObject({ kind: z.literal("tag"), tag: Ref, expand: z.boolean().optional(), ...Weight, conditions: Conds, functions: Fns }),
  z.strictObject({ kind: z.literal("loot_table"), table: Ref, ...Weight, conditions: Conds, functions: Fns }),
  z.strictObject({ kind: z.literal("empty"), weight: Int(1, 1000).optional() }),
]);
export type DpEntry = z.infer<typeof LootEntrySchema>;
export const LootPoolSchema = z.strictObject({ rolls: NumSchema, bonusRolls: z.number().min(0).max(100).optional(), entries: z.array(LootEntrySchema).min(1).max(32), conditions: Conds, functions: Fns });
export const LootTableSchema = z.strictObject({
  kind: z.enum(["generic", "chest", "entity", "block", "fishing", "gift"]).default("generic"),
  pools: z.array(LootPoolSchema).min(1).max(16),
  functions: Fns,
});
export type DpLootTable = z.infer<typeof LootTableSchema>;

export const CriterionSchema = z.discriminatedUnion("trigger", [
  z.strictObject({ trigger: z.literal("impossible") }),
  z.strictObject({ trigger: z.literal("tick") }),
  z.strictObject({ trigger: z.literal("inventory_changed"), items: z.array(Ref).min(1).max(9) }),
  z.strictObject({ trigger: z.literal("consume_item"), item: Ref }),
  z.strictObject({ trigger: z.literal("player_killed_entity"), entity: Ref }),
  z.strictObject({ trigger: z.literal("recipe_unlocked"), recipe: Ref }),
  z.strictObject({ trigger: z.literal("recipe_crafted"), recipe: Ref }),
]);
export type DpCriterion = z.infer<typeof CriterionSchema>;
export const ADVANCEMENT_BACKGROUNDS = ["stone", "adventure", "end", "husbandry", "nether"] as const;
export const AdvancementSchema = z.strictObject({
  /** Own (nx_x:...) or vanilla (minecraft:story/root). Without a parent the advancement starts its own tab (needs display.background). */
  parent: Ref.optional(),
  display: z.strictObject({
    icon: Ref, title: TextSchema, description: TextSchema,
    frame: z.enum(["task", "goal", "challenge"]).optional(),
    background: z.enum(ADVANCEMENT_BACKGROUNDS).optional(),
    showToast: z.boolean().optional(), announceToChat: z.boolean().optional(), hidden: z.boolean().optional(),
  }).optional(),
  criteria: z.record(z.string().regex(/^[a-z0-9_]{1,32}$/), CriterionSchema),
  /** all (default): every criterion; any: one of them. */
  requirements: z.enum(["all", "any"]).optional(),
  rewards: z.strictObject({ experience: Int(0, 10000).optional(), loot: z.array(Ref).max(8).optional(), recipes: z.array(Ref).max(16).optional(), function: Ref.optional() }).optional(),
});
export type DpAdvancement = z.infer<typeof AdvancementSchema>;

export const ENCHANTMENT_SLOTS = ["any", "hand", "mainhand", "offhand", "armor", "feet", "legs", "chest", "head", "body"] as const;
/** Value-effect components the emitter supports (each a list of { effect } in vanilla). Must exist in the target version. */
export const ENCHANTMENT_EFFECTS = ["damage", "damage_protection", "knockback", "armor_effectiveness", "item_damage", "mob_experience", "block_experience", "repair_with_xp", "smash_damage_per_fallen_block"] as const;
const Cost = z.strictObject({ base: Int(0, 1000), perLevelAboveFirst: Int(0, 1000) });
const ItemSet = z.union([Ref, z.array(Ref).min(1).max(32)]);
export const EnchantmentSchema = z.strictObject({
  description: TextSchema,
  /** Items it can be applied to: an item tag (#minecraft:enchantable/sword) or item ids. */
  supportedItems: ItemSet,
  primaryItems: ItemSet.optional(),
  exclusiveSet: z.union([Ref, z.array(Ref).min(1).max(32)]).optional(),
  weight: Int(1, 1024), maxLevel: Int(1, 255), minCost: Cost, maxCost: Cost, anvilCost: Int(0, 255),
  slots: z.array(z.enum(ENCHANTMENT_SLOTS)).min(1).max(4),
  effects: z.array(z.strictObject({ component: z.enum(ENCHANTMENT_EFFECTS), op: z.enum(["add", "multiply", "set"]), base: z.number().min(-1000).max(1000), perLevelAboveFirst: z.number().min(-1000).max(1000).optional() })).max(8).optional(),
});
export type DpEnchantment = z.infer<typeof EnchantmentSchema>;

export const TAG_REGISTRIES = ["item", "block", "entity_type", "function", "enchantment"] as const;
export type TagRegistry = (typeof TAG_REGISTRIES)[number];

export const ResourceSchema = z.discriminatedUnion("type", [
  z.strictObject({ type: z.literal("recipe"), id: RecipePath, recipe: RecipeSchema }),
  z.strictObject({ type: z.literal("loot_table"), id: Path, table: LootTableSchema }),
  z.strictObject({ type: z.literal("advancement"), id: Path, advancement: AdvancementSchema }),
  /**
   * Own tag (`id` = path) or an addition to a vanilla tag (`id` = "minecraft:<existing tag>", replace stays false).
   * Function tags: own, or minecraft:load / minecraft:tick (prefer `runOn` on the function).
   */
  z.strictObject({ type: z.literal("tag"), registry: z.enum(TAG_REGISTRIES), id: z.string().max(80).regex(/^(minecraft:)?[a-z0-9_]+(\/[a-z0-9_]+){0,5}$/), replace: z.boolean().optional(), values: z.array(Ref).min(1).max(256) }),
  /** One command per entry, no leading slash. runOn adds it to #minecraft:load or #minecraft:tick. */
  z.strictObject({ type: z.literal("function"), id: Path, commands: z.array(z.string().max(2000)).min(1).max(256), runOn: z.enum(["load", "tick"]).optional() }),
  z.strictObject({ type: z.literal("enchantment"), id: z.string().regex(/^[a-z0-9_]{1,48}$/), enchantment: EnchantmentSchema }),
]);
export type DpResource = z.infer<typeof ResourceSchema>;
export type DpResourceType = DpResource["type"];

export const DataPackSpecV1Schema = z.strictObject({
  schemaVersion: z.literal(DATAPACK_SPEC_VERSION),
  /** File name (assets/datapack/<name>.json) and pack folder name. */
  name: z.string().regex(/^[a-z][a-z0-9_]{1,31}$/),
  /** pack.mcmeta description. */
  description: z.string().min(1).max(200),
  resources: z.array(ResourceSchema).min(1).max(DATAPACK_LIMITS.maxResources),
});
export type DataPackSpec = z.infer<typeof DataPackSpecV1Schema>;

export function dataPackJsonSchema(): Record<string, unknown> {
  return z.toJSONSchema(DataPackSpecV1Schema, { io: "input" }) as Record<string, unknown>;
}

// ---------------------------------------------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------------------------------------------
export type DpIssue = { path: string; code: string; message: string };
export type CheckStatus = "pass" | "warn" | "fail" | "not_run";
export type DpCheck = { id: string; status: CheckStatus; items: string[] };
export type DpValidation =
  | { ok: true; spec: DataPackSpec; errors: []; warnings: DpIssue[]; checks: DpCheck[]; features: DataPackFeatures }
  | { ok: false; errors: DpIssue[]; warnings: DpIssue[]; checks: DpCheck[] };

export type DpContext = { version: string; namespace: string };

/** Check ids in the order they appear in reports (stable; also used by the service copy). */
export const SPEC_CHECKS = ["schema", "namespace", "vanilla_ids", "references", "version_features", "limits", "function_safety"] as const;

const issuePath = (p: PropertyKey[]) => p.map((x) => (typeof x === "number" ? `[${x}]` : `.${String(x)}`)).join("").replace(/^\./, "");

/** The vanilla-id kind a reference must exist as, per place it is used. */
type RefUse = { at: string; ref: string; kind: IdKind; own?: DpResourceType | "tag:item" | "tag:block" | "tag:entity_type" | "tag:function" | "tag:enchantment" | "function"; tagKind?: IdKind };

export function validateDataPackSpec(input: unknown, ctx: DpContext): DpValidation {
  const errors: DpIssue[] = [];
  const warnings: DpIssue[] = [];
  const bucket = new Map<string, string[]>(SPEC_CHECKS.map((c) => [c, []]));
  const fail = (check: string, path: string, code: string, message: string) => { errors.push({ path, code, message }); bucket.get(check)!.push(`${path}: ${message}`); };
  const warn = (check: string, path: string, code: string, message: string) => { warnings.push({ path, code, message }); bucket.get(check)!.push(`warn ${path}: ${message}`); };
  const checksOf = (ran: Set<string>): DpCheck[] => SPEC_CHECKS.map((id) => {
    const items = bucket.get(id)!;
    const status: CheckStatus = !ran.has(id) ? "not_run" : errors.some((e) => items.includes(`${e.path}: ${e.message}`)) ? "fail" : items.length ? "warn" : "pass";
    return { id, status, items: items.slice(0, 20) };
  });
  const ran = new Set<string>(["schema"]);

  if (!NAMESPACE_RE.test(ctx.namespace)) { fail("namespace", "namespace", "bad_namespace", `"${ctx.namespace}" is not a reserved nx_ namespace`); ran.add("namespace"); return { ok: false, errors, warnings, checks: checksOf(ran) }; }
  const fe = dataPackFeatures(ctx.version);
  ran.add("version_features");
  if (!fe.ok) { fail("version_features", "version", "unsupported_version", fe.error); return { ok: false, errors, warnings, checks: checksOf(ran) }; }
  const v = ctx.version;
  if (input && typeof input === "object" && !Array.isArray(input) && (input as { schemaVersion?: unknown }).schemaVersion !== undefined && (input as { schemaVersion?: unknown }).schemaVersion !== DATAPACK_SPEC_VERSION) {
    fail("schema", "schemaVersion", "schema_version", `schemaVersion must be ${DATAPACK_SPEC_VERSION}`);
    return { ok: false, errors, warnings, checks: checksOf(ran) };
  }
  const parsed = DataPackSpecV1Schema.safeParse(input);
  if (!parsed.success) {
    for (const i of parsed.error.issues.slice(0, 30)) fail("schema", issuePath(i.path) || "(root)", "schema", i.message);
    return { ok: false, errors, warnings, checks: checksOf(ran) };
  }
  const spec = parsed.data;
  for (const c of ["namespace", "vanilla_ids", "references", "limits", "function_safety"]) ran.add(c);
  const ns = ctx.namespace;

  // duplicates + own resource index
  const own = new Map<string, Set<string>>(); // kind -> full ids
  const addOwn = (k: string, id: string) => { if (!own.has(k)) own.set(k, new Set()); own.get(k)!.add(id); };
  const seen = new Set<string>();
  spec.resources.forEach((r, i) => {
    const key = r.type === "tag" ? `tag/${r.registry}:${r.id}` : `${r.type}:${r.id}`;
    if (seen.has(key)) fail("references", `resources[${i}]`, "duplicate_resource", `${r.type} ${r.id} is defined twice`);
    seen.add(key);
    if (r.type === "tag") { if (!r.id.startsWith("minecraft:")) addOwn(`tag:${r.registry}`, `${ns}:${r.id}`); }
    else addOwn(r.type, `${ns}:${r.id}`);
    const kind = r.type === "recipe" ? "recipe" : "resource";
    if (r.type !== "tag" || !r.id.startsWith("minecraft:")) {
      const b = buildIdentifier(ns, kind, r.id.replace(/^minecraft:/, ""));
      if (!b.ok) fail("namespace", `resources[${i}].id`, "bad_id", b.error);
    }
  });

  // collect references
  const refs: RefUse[] = [];
  const ing = (at: string, x: DpIngredient) => (Array.isArray(x) ? x : [x]).forEach((r, j) => refs.push(r.startsWith("#") ? { at: Array.isArray(x) ? `${at}[${j}]` : at, ref: r, kind: "tag/item", own: "tag:item" } : { at: Array.isArray(x) ? `${at}[${j}]` : at, ref: r, kind: "item" }));
  const itemSet = (at: string, x: string | string[]) => ing(at, x);
  const res = (at: string, r: DpResult) => refs.push({ at: `${at}.item`, ref: r.item, kind: "item" });
  const conds = (at: string, cs?: DpCondition[]) => cs?.forEach((c, j) => { if (c.cond === "match_tool") itemSet(`${at}[${j}].items`, c.items); });
  const enchRefs = (at: string, o: string | string[]) => (Array.isArray(o) ? o : [o]).forEach((r) => refs.push(r.startsWith("#") ? { at, ref: r, kind: "tag/enchantment", own: "tag:enchantment" } : { at, ref: r, kind: "enchantment", own: "enchantment" }));
  const fns = (at: string, fs?: DpFunction[]) => fs?.forEach((f, j) => {
    const p = `${at}[${j}]`;
    conds(`${p}.conditions`, f.conditions);
    if ((f.fn === "enchant_randomly" || f.fn === "enchant_with_levels") && f.options) enchRefs(`${p}.options`, f.options);
    if (f.fn === "set_enchantments") for (const k of Object.keys(f.enchantments)) enchRefs(`${p}.enchantments`, k);
    if (f.fn === "set_damage" && typeof f.damage === "number" && (f.damage < 0 || f.damage > 1)) fail("schema", `${p}.damage`, "range", "damage is a fraction between 0 and 1");
  });
  const fnRefs: { at: string; ref: string }[] = [];
  spec.resources.forEach((r, i) => {
    const at = `resources[${i}]`;
    if (r.type === "recipe") {
      const rc = r.recipe;
      if (rc.kind === "shaped") {
        const width = rc.pattern[0].length;
        if (rc.pattern.some((row) => row.length !== width)) fail("schema", `${at}.recipe.pattern`, "pattern_rows", "every pattern row must have the same length");
        const used = new Set(rc.pattern.join("").replace(/ /g, "").split(""));
        for (const ch of used) if (!(ch in rc.key)) fail("references", `${at}.recipe.pattern`, "pattern_key", `pattern uses "${ch}" but key has no "${ch}"`);
        for (const k of Object.keys(rc.key)) { if (!used.has(k)) warn("references", `${at}.recipe.key.${k}`, "unused_key", `key "${k}" is not used in the pattern`); ing(`${at}.recipe.key.${k}`, rc.key[k]); }
      } else if (rc.kind === "shapeless") rc.ingredients.forEach((x, j) => ing(`${at}.recipe.ingredients[${j}]`, x));
      else if (rc.kind === "smithing_transform") { ing(`${at}.recipe.template`, rc.template); ing(`${at}.recipe.base`, rc.base); ing(`${at}.recipe.addition`, rc.addition); }
      else ing(`${at}.recipe.ingredient`, rc.ingredient);
      res(`${at}.recipe.result`, rc.result);
      if (rc.result.item.replace(/^minecraft:/, "") === "air") fail("vanilla_ids", `${at}.recipe.result.item`, "air", "a recipe cannot make air");
      if (["smelting", "blasting", "smoking", "campfire_cooking"].includes(rc.kind)) {
        if ((rc.result.count ?? 1) > 1 && !fe.features.cookingResultCount) fail("version_features", `${at}.recipe.result.count`, "version_unsupported", `cooking results with a count need Minecraft 26.1 or newer (this pack targets ${v})`);
        if (rc.result.name || rc.result.lore) fail("version_features", `${at}.recipe.result`, "unsupported", "cooking results cannot carry a name or lore in Cyrus data packs; use a crafting recipe");
      }
    } else if (r.type === "loot_table") {
      fns(`${at}.table.functions`, r.table.functions);
      r.table.pools.forEach((p, j) => {
        const pa = `${at}.table.pools[${j}]`;
        conds(`${pa}.conditions`, p.conditions); fns(`${pa}.functions`, p.functions);
        if (r.table.kind !== "entity" && p.conditions?.some((c) => c.cond === "killed_by_player")) warn("references", `${pa}.conditions`, "context", "killed_by_player only works in entity loot tables");
        p.entries.forEach((e, k) => {
          const ea = `${pa}.entries[${k}]`;
          if (e.kind === "item") refs.push({ at: `${ea}.item`, ref: e.item, kind: "item" });
          if (e.kind === "tag") { if (!e.tag.startsWith("#")) fail("schema", `${ea}.tag`, "tag_ref", "a tag entry needs a #tag id"); else refs.push({ at: `${ea}.tag`, ref: e.tag, kind: "tag/item", own: "tag:item" }); }
          if (e.kind === "loot_table") refs.push({ at: `${ea}.table`, ref: e.table, kind: "loot_table", own: "loot_table" });
          if (e.kind !== "empty") { conds(`${ea}.conditions`, e.conditions); fns(`${ea}.functions`, e.functions); }
        });
      });
    } else if (r.type === "advancement") {
      const a = r.advancement;
      if (a.parent) refs.push({ at: `${at}.advancement.parent`, ref: a.parent, kind: "advancement", own: "advancement" });
      if (a.display) {
        refs.push({ at: `${at}.advancement.display.icon`, ref: a.display.icon, kind: "item" });
        if (!a.parent && !a.display.background) fail("references", `${at}.advancement.display.background`, "root_background", "an advancement without a parent starts a new tab and needs display.background");
        if (a.parent && a.display.background) warn("references", `${at}.advancement.display.background`, "background_ignored", "background only matters on a root advancement (no parent)");
      }
      const names = Object.keys(a.criteria);
      if (!names.length) fail("schema", `${at}.advancement.criteria`, "no_criteria", "an advancement needs at least one criterion");
      if (names.length > 16) fail("limits", `${at}.advancement.criteria`, "too_many", "at most 16 criteria");
      for (const n of names) {
        const c = a.criteria[n], ca = `${at}.advancement.criteria.${n}`;
        if (c.trigger === "inventory_changed") c.items.forEach((x, j) => refs.push(x.startsWith("#") ? { at: `${ca}.items[${j}]`, ref: x, kind: "tag/item", own: "tag:item" } : { at: `${ca}.items[${j}]`, ref: x, kind: "item" }));
        if (c.trigger === "consume_item") refs.push(c.item.startsWith("#") ? { at: `${ca}.item`, ref: c.item, kind: "tag/item", own: "tag:item" } : { at: `${ca}.item`, ref: c.item, kind: "item" });
        if (c.trigger === "player_killed_entity") refs.push(c.entity.startsWith("#") ? { at: `${ca}.entity`, ref: c.entity, kind: "tag/entity_type", own: "tag:entity_type" } : { at: `${ca}.entity`, ref: c.entity, kind: "entity_type" });
        if (c.trigger === "recipe_unlocked" || c.trigger === "recipe_crafted") refs.push({ at: `${ca}.recipe`, ref: c.recipe, kind: "recipe", own: "recipe" });
      }
      a.rewards?.loot?.forEach((x, j) => refs.push({ at: `${at}.advancement.rewards.loot[${j}]`, ref: x, kind: "loot_table", own: "loot_table" }));
      a.rewards?.recipes?.forEach((x, j) => refs.push({ at: `${at}.advancement.rewards.recipes[${j}]`, ref: x, kind: "recipe", own: "recipe" }));
      if (a.rewards?.function) fnRefs.push({ at: `${at}.advancement.rewards.function`, ref: a.rewards.function });
    } else if (r.type === "tag") {
      const vanillaTag = r.id.startsWith("minecraft:");
      if (vanillaTag) {
        if (r.replace) fail("references", `${at}.replace`, "replace_vanilla", `replace: true on ${r.id} would wipe the vanilla tag (and every other pack's additions); Cyrus only appends`);
        if (r.registry === "function") { if (!["minecraft:load", "minecraft:tick"].includes(r.id)) fail("references", `${at}.id`, "function_tag", "the only vanilla function tags are minecraft:load and minecraft:tick"); }
        else if (!isVanilla(`tag/${r.registry}` as IdKind, r.id, v)) fail("vanilla_ids", `${at}.id`, "unknown_vanilla_tag", `#${r.id} is not a ${r.registry} tag in Minecraft ${v}`);
      } else if (r.replace) warn("references", `${at}.replace`, "replace_own", "replace: true on your own tag only matters if another pack adds to it");
      r.values.forEach((x, j) => {
        const p = `${at}.values[${j}]`;
        if (r.registry === "function") { if (x.startsWith("#")) fail("references", p, "function_tag_value", "function tags list functions, not other tags"); else fnRefs.push({ at: p, ref: x }); return; }
        const kind = (r.registry === "item" ? "item" : r.registry === "block" ? "block" : r.registry === "entity_type" ? "entity_type" : "enchantment") as IdKind;
        refs.push(x.startsWith("#") ? { at: p, ref: x, kind: `tag/${r.registry}` as IdKind, own: `tag:${r.registry}` as RefUse["own"] } : { at: p, ref: x, kind, ...(r.registry === "enchantment" ? { own: "enchantment" as const } : {}) });
      });
    } else if (r.type === "enchantment") {
      const e = r.enchantment;
      itemSet(`${at}.enchantment.supportedItems`, e.supportedItems);
      if (e.primaryItems) itemSet(`${at}.enchantment.primaryItems`, e.primaryItems);
      if (e.exclusiveSet) enchRefs(`${at}.enchantment.exclusiveSet`, e.exclusiveSet);
      if (e.maxCost.base < e.minCost.base) warn("references", `${at}.enchantment.maxCost`, "cost_order", "maxCost.base is below minCost.base: the enchanting table never offers it");
      e.effects?.forEach((x, j) => { if (!isVanilla("enchantment_effect_component_type", x.component, v)) fail("version_features", `${at}.enchantment.effects[${j}].component`, "unknown_effect", `effect component ${x.component} does not exist in Minecraft ${v}`); });
    }
  });

  // resolve references
  for (const u of refs) {
    const nsOf = u.ref.replace(/^#/, "").split(":")[0];
    if (nsOf === "minecraft") {
      if (!isVanilla(u.kind, u.ref, v)) {
        const first = firstVersionWith(u.kind, u.ref);
        fail("vanilla_ids", u.at, "unknown_vanilla_id", first ? `${u.ref} needs Minecraft ${first} or newer (this pack targets ${v})` : `${u.ref} is not a ${u.kind.replace("tag/", "")}${u.kind.startsWith("tag/") ? " tag" : ""} in Minecraft ${v}`);
      }
    } else if (nsOf === ns) {
      if (!u.own) fail("references", u.at, "not_definable", `${u.ref}: a data pack cannot define new ${u.kind}s (only vanilla ${u.kind}s can be used here)`);
      else if (!own.get(u.own)?.has(u.ref.replace(/^#/, ""))) fail("references", u.at, "unresolved_ref", `${u.ref} is not defined in this pack`);
    } else fail("namespace", u.at, "foreign_namespace", `${u.ref} uses the namespace ${nsOf}; this pack may only use minecraft: and its own ${ns}`);
  }

  // functions: safety + call graph (tags resolved against this pack)
  const fnList = spec.resources.filter((r): r is Extract<DpResource, { type: "function" }> => r.type === "function");
  const functionTags = new Map<string, string[]>();
  const tickFns: string[] = [], loadFns: string[] = [];
  for (const r of spec.resources) if (r.type === "tag" && r.registry === "function") {
    const full = r.id.startsWith("minecraft:") ? r.id : `${ns}:${r.id}`;
    functionTags.set(`#${full}`, r.values.filter((x) => !x.startsWith("#")));
    if (full === "minecraft:tick") tickFns.push(...r.values); if (full === "minecraft:load") loadFns.push(...r.values);
  }
  for (const u of fnRefs) {
    if (!u.ref.startsWith(`${ns}:`)) fail("references", u.at, "function_ref", `${u.ref}: only this pack's own functions can be referenced`);
    else if (!fnList.some((f) => `${ns}:${f.id}` === u.ref)) fail("references", u.at, "unresolved_ref", `function ${u.ref} is not defined in this pack`);
  }
  const fr = checkFunctions(fnList.map((f) => ({ id: f.id, commands: f.commands, runOn: f.runOn })), {
    namespace: ns, versionCommands: vanillaIds("command", v), versionGamerules: vanillaIds("gamerule", v), functionTags, tickFunctions: tickFns, loadFunctions: loadFns,
  });
