import type { DataPackFeatures } from "../versions";
import type { DpCondition, DpEntry, DpFunction, DpLootTable } from "../spec";
import { numberProvider, textComponent, type Json } from "./common";

const opt = <T>(k: string, v: T | undefined, f: (x: T) => Json = (x) => x as unknown as Json): { [k: string]: Json } => (v === undefined ? {} : { [k]: f(v) });
const listOrOne = (x: string | string[]): Json => (Array.isArray(x) ? x : x);

export function emitCondition(c: DpCondition): Json {
  switch (c.cond) {
    case "random_chance": return { condition: "minecraft:random_chance", chance: c.chance };
    case "killed_by_player": return { condition: "minecraft:killed_by_player" };
    case "survives_explosion": return { condition: "minecraft:survives_explosion" };
    case "match_tool": return { condition: "minecraft:match_tool", predicate: { items: listOrOne(c.items) } };
    case "weather": return { condition: "minecraft:weather_check", ...opt("raining", c.raining), ...opt("thundering", c.thundering) };
  }
}
const conds = (cs?: DpCondition[]) => (cs?.length ? { conditions: cs.map(emitCondition) } : {});

export function emitFunction(f: DpFunction, _fe: DataPackFeatures): Json {
  const c = conds(f.conditions);
  switch (f.fn) {
    case "set_count": return { function: "minecraft:set_count", count: numberProvider(f.count), ...opt("add", f.add), ...c };
    case "set_damage": return { function: "minecraft:set_damage", damage: numberProvider(f.damage), ...c };
    case "enchant_randomly": return { function: "minecraft:enchant_randomly", ...opt("options", f.options, listOrOne), ...c };
    case "enchant_with_levels": return { function: "minecraft:enchant_with_levels", levels: numberProvider(f.levels), ...opt("options", f.options, listOrOne), ...c };
    case "set_name": return { function: "minecraft:set_name", name: textComponent(f.name), target: f.target ?? "item_name", ...c };
    case "set_lore": return { function: "minecraft:set_lore", lore: f.lore.map(textComponent), mode: f.mode ?? "append", ...c };
    case "set_enchantments": {
      const e: { [k: string]: Json } = {};
      for (const k of Object.keys(f.enchantments).sort()) e[k] = f.enchantments[k];
      return { function: "minecraft:set_enchantments", enchantments: e, ...opt("add", f.add), ...c };
    }
    case "explosion_decay": return { function: "minecraft:explosion_decay", ...c };
    case "furnace_smelt": return { function: "minecraft:furnace_smelt", ...c };
    case "looting_bonus": return { function: "minecraft:enchanted_count_increase", enchantment: "minecraft:looting", count: numberProvider(f.count), ...c };
  }
}
const fns = (fs: DpFunction[] | undefined, fe: DataPackFeatures) => (fs?.length ? { functions: fs.map((f) => emitFunction(f, fe)) } : {});

export function emitEntry(e: DpEntry, fe: DataPackFeatures): Json {
  if (e.kind === "empty") return { type: "minecraft:empty", ...opt("weight", e.weight) };
  const common = { ...opt("weight", e.weight), ...opt("quality", e.quality), ...conds(e.conditions), ...fns(e.functions, fe) };
  if (e.kind === "item") return { type: "minecraft:item", name: e.item, ...common };
  // tag entries: `expand` is REQUIRED before 26.3 (vanilla-mcdoc); always written
  if (e.kind === "tag") return { type: "minecraft:tag", name: e.tag.replace(/^#/, ""), expand: e.expand ?? false, ...common };
  // loot_table entries reference another table by `value` (since 1.20.5; vanilla-mcdoc)
  return { type: "minecraft:loot_table", value: e.table, ...common };
}

const LOOT_TYPE: Record<DpLootTable["kind"], string> = { generic: "minecraft:generic", chest: "minecraft:chest", entity: "minecraft:entity", block: "minecraft:block", fishing: "minecraft:fishing", gift: "minecraft:gift" };

export function emitLootTable(t: DpLootTable, fe: DataPackFeatures, randomSequence: string): Json {
  return {
    type: LOOT_TYPE[t.kind],
    pools: t.pools.map((p) => ({ rolls: numberProvider(p.rolls), ...opt("bonus_rolls", p.bonusRolls), entries: p.entries.map((e) => emitEntry(e, fe)), ...conds(p.conditions), ...fns(p.functions, fe) })),
    ...fns(t.functions, fe),
    random_sequence: randomSequence,
  };
}
