import type { DataPackFeatures } from "../versions";
import type { DpAdvancement, DpCriterion } from "../spec";
import { textComponent, type Json } from "./common";

const itemPredicate = (r: string): Json => ({ items: r });

/** Entity type predicate: plain {"type": id} before 26.2, namespaced sub-predicates {"minecraft:entity_type": id} from 26.2 (verified). */
const entityType = (r: string, fe: DataPackFeatures): Json => (fe.entityPredicate === "sub-map" ? { "minecraft:entity_type": r } : { type: r });

export function emitCriterion(c: DpCriterion, fe: DataPackFeatures): Json {
  switch (c.trigger) {
    case "impossible": return { trigger: "minecraft:impossible" };
    case "tick": return { trigger: "minecraft:tick" };
    case "inventory_changed": return { trigger: "minecraft:inventory_changed", conditions: { items: c.items.map(itemPredicate) } };
    case "consume_item": return { trigger: "minecraft:consume_item", conditions: { item: itemPredicate(c.item) } };
    case "player_killed_entity": return { trigger: "minecraft:player_killed_entity", conditions: { entity: entityType(c.entity, fe) } };
    case "recipe_unlocked": return { trigger: "minecraft:recipe_unlocked", conditions: { recipe: c.recipe } };
    case "recipe_crafted": return { trigger: "minecraft:recipe_crafted", conditions: { recipe_id: c.recipe } };
  }
}

export function emitAdvancement(a: DpAdvancement, fe: DataPackFeatures): Json {
  const out: { [k: string]: Json } = {};
  if (a.parent) out.parent = a.parent;
  if (a.display) {
    const d = a.display;
    const icon: { [k: string]: Json } = { id: d.icon };
    if (fe.iconCount) icon.count = 1;
    out.display = {
      icon, title: textComponent(d.title), description: textComponent(d.description),
      ...(d.frame ? { frame: d.frame } : {}),
      ...(d.background ? { background: fe.background === "id" ? `minecraft:gui/advancements/backgrounds/${d.background}` : `minecraft:textures/gui/advancements/backgrounds/${d.background}.png` } : {}),
      ...(d.showToast !== undefined ? { show_toast: d.showToast } : {}), ...(d.announceToChat !== undefined ? { announce_to_chat: d.announceToChat } : {}), ...(d.hidden !== undefined ? { hidden: d.hidden } : {}),
    };
  }
  const names = Object.keys(a.criteria).sort();
  const criteria: { [k: string]: Json } = {};
  for (const n of names) criteria[n] = emitCriterion(a.criteria[n], fe);
  out.criteria = criteria;
  out.requirements = a.requirements === "any" ? [names] : names.map((n) => [n]);
  if (a.rewards) {
    const r = a.rewards;
    out.rewards = { ...(r.experience !== undefined ? { experience: r.experience } : {}), ...(r.loot?.length ? { loot: r.loot } : {}), ...(r.recipes?.length ? { recipes: r.recipes } : {}), ...(r.function ? { function: r.function } : {}) };
  }
  return out;
}
