// Static validator for data pack FILES (what the emitters wrote, or raw JSON from an imported pack), per version:
//   mcmeta         pack.mcmeta shape (pack_format before 1.21.9, min_format/max_format after) and the registry's number
//   mcdoc_fields   top-level keys of recipes / loot tables / pools / entries / functions / conditions / advancements /
//                  criteria / enchantments against the vanilla-mcdoc field tables (./mcdoc.ts)
//   value_shapes   the format changes that break packs silently: ingredient shape (1.21.2), text in item components
//                  (1.21.5), advancement background (1.21.5), entity predicates (26.2), cooking result count (26.1)
//   vanilla_ids    recipe types, loot function / condition types, triggers, items in results and ingredients exist
//   function_safety the .mcfunction allowlist (./functions.ts)
//   not_checked    resources outside the studio's subset (worldgen, predicates, ...): listed, kept, never judged
// Pure: works on { path, text } pairs. A check that found nothing to look at is "pass" with an empty list.
import { checkFunctions } from "./functions";
import { checkKeys, dispatchFields, structFields } from "./mcdoc";
import type { CheckStatus, DpCheck } from "./spec";
import { dataPackFeatures, isVanilla, vanillaIds, type DataPackFeatures, type IdKind } from "./versions";

export const FILE_CHECKS = ["mcmeta", "mcdoc_fields", "value_shapes", "vanilla_ids", "function_safety", "not_checked"] as const;
export type PackFile = { path: string; text: string };
export type FileReport = { ok: boolean; version: string; checks: DpCheck[]; errors: string[]; warnings: string[]; notChecked: string[] };

const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);
const COOKING = ["minecraft:smelting", "minecraft:blasting", "minecraft:smoking", "minecraft:campfire_cooking"];

/** data/<ns>/<type>/<path>.<ext> -> parts (singular folders only: the studio's floor is 1.21.1). */
export function dataPath(p: string): { ns: string; type: string; id: string; ext: string } | null {
  const m = /^data\/([a-z0-9_.-]+)\/((?:tags\/[a-z_]+)|[a-z_]+)\/([a-z0-9_./-]+)\.(json|mcfunction)$/.exec(p);
  if (!m) return null;
  return { ns: m[1], type: m[2], id: `${m[1]}:${m[3]}`, ext: m[4] };
}

export function validatePackFiles(files: PackFile[], version: string): FileReport {
  const items = new Map<string, string[]>(FILE_CHECKS.map((c) => [c, []]));
  const failed = new Set<string>();
  const errors: string[] = [], warnings: string[] = [], notChecked: string[] = [];
  const fail = (c: string, m: string) => { failed.add(c); items.get(c)!.push(m); errors.push(m); };
  const warn = (c: string, m: string) => { items.get(c)!.push(`warn ${m}`); warnings.push(m); };
  const fr = dataPackFeatures(version);
  const finish = (): FileReport => ({
    ok: errors.length === 0, version, errors, warnings, notChecked,
    checks: FILE_CHECKS.map((id) => ({ id, status: (failed.has(id) ? "fail" : items.get(id)!.length ? (id === "not_checked" ? "warn" : "warn") : "pass") as CheckStatus, items: items.get(id)!.slice(0, 20) })),
  });
  if (!fr.ok) { fail("mcmeta", fr.error); return finish(); }
  const fe = fr.features;

  const mc = files.find((f) => f.path === "pack.mcmeta");
  if (!mc) fail("mcmeta", "pack.mcmeta is missing (Minecraft ignores the pack)");
  else checkMcmeta(mc.text, fe, (m) => fail("mcmeta", m));

  const fnFiles: { id: string; commands: string[] }[] = [];
  const nsSet = new Set<string>();
  for (const f of [...files].sort((a, b) => (a.path < b.path ? -1 : 1))) {
    if (f.path === "pack.mcmeta" || f.path === "pack.png") continue;
    const d = dataPath(f.path);
    if (!d) { notChecked.push(f.path); continue; }
    nsSet.add(d.ns);
    if (d.ext === "mcfunction") { if (d.type === "function") fnFiles.push({ id: d.id, commands: f.text.split(/\r?\n/) }); else notChecked.push(f.path); continue; }
    let j: unknown;
    try { j = JSON.parse(f.text.replace(/^﻿/, "")); } catch (e) { fail("mcdoc_fields", `${f.path}: not valid JSON (${(e as Error).message.slice(0, 80)})`); continue; }
    const ctx: Ctx = { at: f.path, fe, v: version, fail, warn };
    if (d.type === "recipe") checkRecipe(j, ctx);
    else if (d.type === "loot_table") checkLoot(j, ctx);
    else if (d.type === "advancement") checkAdvancement(j, ctx);
    else if (d.type === "enchantment") checkEnchantment(j, ctx);
    else if (d.type.startsWith("tags/")) checkTag(j, ctx);
    else notChecked.push(f.path);
  }
  // functions per namespace (the allowlist does not depend on the namespace; calls must stay inside it)
  for (const ns of [...nsSet].sort()) {
    const mine = fnFiles.filter((x) => x.id.startsWith(`${ns}:`));
    if (!mine.length) continue;
    const r = checkFunctions(mine.map((x) => ({ id: x.id.slice(ns.length + 1), commands: x.commands })), { namespace: ns, versionCommands: vanillaIds("command", version), versionGamerules: vanillaIds("gamerule", version) });
    for (const x of r.findings) (x.severity === "error" ? (m: string) => fail("function_safety", m) : (m: string) => warn("function_safety", m))(`${x.at}: ${x.message}`);
  }
  for (const p of notChecked) items.get("not_checked")!.push(p);
  return finish();
}

type Ctx = { at: string; fe: DataPackFeatures; v: string; fail: (c: string, m: string) => void; warn: (c: string, m: string) => void };

function checkMcmeta(text: string, fe: DataPackFeatures, fail: (m: string) => void) {
  let j: unknown;
  try { j = JSON.parse(text); } catch { return fail("pack.mcmeta is not valid JSON"); }
  const p = isObj(j) ? j.pack : null;
  if (!isObj(p)) return fail("pack.mcmeta has no pack object");
  if (p.description === undefined) fail("pack.mcmeta needs a description");
  const { major, minor } = fe.format;
  if (fe.mcmeta === "pack_format") {
    if (p.pack_format !== major) fail(`pack.mcmeta pack_format must be ${major} for Minecraft ${fe.version} (is ${JSON.stringify(p.pack_format)})`);
    if ("min_format" in p || "max_format" in p) fail("min_format / max_format only exist from 1.21.9");
  } else {
    const ok = (x: unknown) => Array.isArray(x) && x[0] === major && (x[1] ?? 0) === minor || x === major && minor === 0;
    if (!ok(p.min_format) || !ok(p.max_format)) fail(`pack.mcmeta needs min_format and max_format [${major}, ${minor}] for Minecraft ${fe.version}`);
    if ("supported_formats" in p) fail("supported_formats must not be used with min_format (1.21.9+)");
  }
}

function keys(ctx: Ctx, where: string, obj: Record<string, unknown>, t: ReturnType<typeof structFields>, ignore: string[] = []) {
  const r = checkKeys(obj, t, ignore);
  for (const k of r.unknown) ctx.fail("mcdoc_fields", `${ctx.at}: ${where} has the key "${k}", which Minecraft ${ctx.v} does not know`);
  for (const k of r.missing) ctx.fail("mcdoc_fields", `${ctx.at}: ${where} is missing the required key "${k}" for Minecraft ${ctx.v}`);
}
function vid(ctx: Ctx, kind: IdKind, id: unknown, what: string) {
  if (typeof id !== "string") return ctx.fail("value_shapes", `${ctx.at}: ${what} must be an id string`);
  if (id.replace(/^#/, "").startsWith("minecraft:") || !id.includes(":")) {
    if (!isVanilla(kind, id, ctx.v)) ctx.fail("vanilla_ids", `${ctx.at}: ${what} ${id} does not exist in Minecraft ${ctx.v}`);
  }
}

function checkIngredient(ctx: Ctx, x: unknown, where: string) {
  const one = (y: unknown, inList: boolean) => {
    if (ctx.fe.ingredient === "string") {
      if (typeof y !== "string") return ctx.fail("value_shapes", `${ctx.at}: ${where} must be an item id or #tag string on Minecraft ${ctx.v} (1.21.2+), not ${JSON.stringify(y).slice(0, 60)}`);
      if (inList && y.startsWith("#")) return ctx.fail("value_shapes", `${ctx.at}: ${where}: a list of alternatives may only hold item ids on ${ctx.v} (use one #tag instead)`);
      vid(ctx, y.startsWith("#") ? "tag/item" : "item", y, where);
    } else {
      if (!isObj(y) || (typeof y.item !== "string" && typeof y.tag !== "string")) return ctx.fail("value_shapes", `${ctx.at}: ${where} must be {"item": id} or {"tag": id} on Minecraft ${ctx.v}`);
      if (typeof y.item === "string") vid(ctx, "item", y.item, where); else vid(ctx, "tag/item", y.tag, where);
    }
  };
  if (Array.isArray(x)) { if (!x.length) ctx.fail("value_shapes", `${ctx.at}: ${where} is an empty list`); x.forEach((y) => one(y, true)); } else one(x, false);
}

