const hash = (alg: "sha1" | "sha256", b: Buffer | string) => createHash(alg).update(b).digest("hex");

export function buildDataPack(input: unknown, ctx: { version: string; namespace: string }): BuildResult {
  const v = validateDataPackSpec(input, ctx);
  if (!v.ok) return { ok: false, errors: v.errors.map((e) => `${e.path}: ${e.message}`), issues: v.errors, checks: v.checks };
  const files = emitFiles(v.spec, ctx.namespace, v.features);
  const fileReport = validatePackFiles(files, ctx.version);
  const checks = [...v.checks, ...fileReport.checks.map((c) => ({ ...c, id: c.id === "vanilla_ids" ? "emitted_ids" : c.id === "function_safety" ? "emitted_functions" : c.id }))];
  if (!fileReport.ok) return { ok: false, errors: fileReport.errors.map((e) => `emitted: ${e}`), issues: [], checks, fileReport };
  const z = zip(files.map((f) => ({ path: f.path, data: Buffer.from(f.text, "utf8") })));
  const counts: Record<string, number> = {};
  for (const r of v.spec.resources) counts[r.type] = (counts[r.type] ?? 0) + 1;
  if (z.length > 1024 * 1024) return { ok: false, errors: [`the data pack is ${z.length} bytes; the limit is 1 MB`], issues: [], checks, fileReport };
  return {
    ok: true,
    pack: {
      name: v.spec.name, version: ctx.version, namespace: ctx.namespace, files, zip: z, sha1: hash("sha1", z), sha256: hash("sha256", z), bytes: z.length,
      format: v.features.format, specSha256: hash("sha256", canonicalJson(v.spec)), counts, apply: needsRestart(v.spec) ? "restart" : "reload",
      checks, warnings: [...v.warnings.map((w) => `${w.path}: ${w.message}`), ...fileReport.warnings], emitter: EMITTER_VERSION,
    },
  };
}
