// Cyrus R2 data pack studio: does a BUILD get the data pack route? Pure + deterministic (no AI call), client-safe.
// The capability router's rules (adapter route rules with route "dataPack") read the request; worldgen alone never
// turns the route on (not built). OFF unless CYRUS_DATAPACK_STUDIO=1 (fail closed): off, nothing is decided, nothing
// is recorded and the build request stays byte-identical. Data packs are NOT plan-gated (owner decision for
// composition features): no plan lookup happens here.
import { getAdapter } from "../adapters";
import { routeSpec, type RouteDecision } from "../engine-core/router";
import type { ModSpec } from "../engine-core/spec";
import { dataPackFeatures } from "./versions";

export const DATAPACK_FLAG = "CYRUS_DATAPACK_STUDIO";
/** Adapter rule ids that mean "data-driven content the studio can build". `worldgen` is deliberately not here. */
export const DATAPACK_RULES = ["datapack_recipe", "datapack_loot", "datapack_advancement", "datapack_tag", "datapack_function", "datapack_enchantment", "datapack_content"] as const;

export const dataPackStudioOn = (env: Record<string, string | undefined> = process.env) => env[DATAPACK_FLAG] === "1";

export type DataPackRouteInput = {
  text: string;
  /** body.assets (a REQUEST only): ["datapack"] or { datapack: true }. */
  explicit?: unknown;
  /** The base build already ships data packs (a change keeps working on them). */
  existing?: boolean;
  mcVersion: string;
  game?: string;
  on: boolean;
};
export type DataPackRouteDecision = { route: boolean; matched: string[]; notices: string[]; limits: string[] };

const explicitDatapack = (raw: unknown) => (Array.isArray(raw) ? raw.includes("datapack") : !!raw && typeof raw === "object" && (raw as Record<string, unknown>).datapack === true);

/** Which data pack rules the adapter matches in this text (the router's own keyword rules, no AI). */
export function matchDataPackRules(text: string, game = "minecraft"): string[] {
  const adapter = getAdapter(game);
  if (!adapter || !text) return [];
