  if (!fe.ok) return { route: false, matched, notices: [`Data packs aren't available for Minecraft ${i.mcVersion} yet (${fe.error}), so Cyrus builds this as a plugin only.`], limits: [] };
  const adapter = getAdapter(i.game ?? "minecraft");
  const limits = (adapter?.routeRules ?? []).filter((r) => matched.includes(r.id) && r.limit).map((r) => r.limit!.message);
  return { route: true, matched, notices: [], limits };
}

/** Route a typed spec with the data pack route switched on where the host enabled it (wraps the engine router). */
export function routeWithDataPack(spec: ModSpec, opts: { prompt?: string; gate?: { plan: unknown }; env?: Record<string, string | undefined> } = {}): RouteDecision | null {
  const adapter = getAdapter(spec.game);
  if (!adapter) return null;
  return routeSpec(spec, adapter, { prompt: opts.prompt, gate: opts.gate, routesOn: dataPackStudioOn(opts.env) ? ["dataPack"] : [] });
}

