// Cyrus R2 data pack studio, PORTAL side of a succeeded build: the service's data pack specs are never trusted.
// Each returned spec is validated and emitted AGAIN here with the TypeScript emitter for the build's exact version;
// a spec that fails is dropped with a reason (never shipped). The zip is deterministic, so the portal does not need
// to store it: delivery rebuilds it from the spec kept in the CyrusProjectAsset row and checks the recorded sha256.
import { buildDataPack, type BuiltDataPack } from "./emit";
import { canonicalJson, type DataPackSpec } from "./spec";

export const DATAPACK_SPEC_MIME = "application/vnd.nxeon.datapack-spec+json";
export type SvcDatapack = { name: string; path: string; sha256: string; spec: unknown; pack?: { sha256?: string } | null };
export type CheckedDatapack = { name: string; spec: DataPackSpec; canonical: string; specSha256: string; pack: BuiltDataPack; serviceAgreed: boolean };

export function checkReturnedDatapacks(list: SvcDatapack[] | undefined, ctx: { namespace: string; mcVersion: string }): { ok: CheckedDatapack[]; dropped: { name: string; reason: string }[]; notices: string[] } {
  const ok: CheckedDatapack[] = [], dropped: { name: string; reason: string }[] = [], notices: string[] = [];
  const owners = new Map<string, string>();
  for (const d of (list ?? []).slice(0, 4)) {
    const name = typeof d?.name === "string" ? d.name.slice(0, 40) : "?";
    const b = buildDataPack(d?.spec, { version: ctx.mcVersion, namespace: ctx.namespace });
    if (!b.ok) { dropped.push({ name, reason: b.errors[0] ?? "failed the data pack checks" }); notices.push(`Data pack "${name}" was left out: it did not pass Nxeon's data pack checks for Minecraft ${ctx.mcVersion}.`); continue; }
    if (b.pack.name !== name || ok.some((x) => x.name === name)) { dropped.push({ name, reason: "name mismatch or duplicate" }); continue; }
    const spec = d.spec as DataPackSpec;
    const clash = spec.resources.map((r) => (r.type === "tag" ? `tag/${r.registry}:${r.id}` : `${r.type}:${r.id}`)).find((k) => owners.has(k) && !/^tag\/[a-z_]+:minecraft:/.test(k));
    if (clash) { dropped.push({ name, reason: `${clash} is also defined in ${owners.get(clash)}` }); notices.push(`Data pack "${name}" was left out: it defines ${clash} a second time.`); continue; }
    for (const r of spec.resources) owners.set(r.type === "tag" ? `tag/${r.registry}:${r.id}` : `${r.type}:${r.id}`, name);
    const canonical = canonicalJson(b.pack ? spec : spec);
    ok.push({ name, spec, canonical, specSha256: b.pack.specSha256, pack: b.pack, serviceAgreed: !d.pack?.sha256 || d.pack.sha256 === b.pack.sha256 });
  }
  return { ok, dropped, notices };
}
