// Cyrus R2 data pack studio: EDIT / IMPORT support for existing data packs (pure; nothing is executed or loaded).
//
// importDataPackZip(buf): read a data pack zip with the bounded zip reader (lib/cyrus/inventory/zipread.ts: entry,
// ratio and total budgets, CRC, unsafe names reported, never extracted) and turn what fits the studio subset into a
// DataPackSpec (recipes, loot tables, tags, advancements, functions of the pack's main namespace). Everything else is
// kept as a RAW resource, byte for byte: worldgen, predicates, item modifiers, structures, vanilla overrides, unknown
// fields, pack.png, overlays... Nothing is ever discarded.
// exportImported(imp, edits): the files again. An unchanged converted resource is written with its ORIGINAL bytes, so
// import -> export without edits is an exact round trip; an edited one is re-emitted for the target version; raw
// resources can be replaced as text and are validated with the static file validator (./validate.ts).
// This is a library for the import flow (another agent wires the upload); it never touches a server.
import { createHash } from "node:crypto";
import { indexZip, readEntry, DEFAULT_ZIP_LIMITS, type ZipLimits } from "../inventory/zipread";
import { zip as writeZip } from "../textures/zip";
import { emitFiles } from "./emit";
import { canonicalJson, validateDataPackSpec, type DataPackSpec, type DpCondition, type DpCriterion, type DpEntry, type DpFunction, type DpIngredient, type DpNum, type DpResource, type DpResult, type DpText, TEXT_COLORS, ADVANCEMENT_BACKGROUNDS } from "./spec";
import { dataPath, validatePackFiles, type FileReport, type PackFile } from "./validate";
import { dataPackFeatures } from "./versions";

export const IMPORT_LIMITS: ZipLimits = { ...DEFAULT_ZIP_LIMITS, maxEntries: 5000, maxEntryBytes: 1024 * 1024, maxTotalBytes: 32 * 1024 * 1024 };

export type RawResource = { path: string; bytes: Buffer; sha256: string; reason: string };
export type ConvertedResource = { path: string; index: number; original: Buffer; canonical: string };
export type ImportedPack = {
  ok: true;
  namespace: string | null;
  description: string;
  packFormat: unknown;
  spec: DataPackSpec | null;
  converted: ConvertedResource[];
  raw: RawResource[];
  issues: string[];
};
export type ImportResult = ImportedPack | { ok: false; error: string };

const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
class NoFit extends Error {}
const no = (why: string): never => { throw new NoFit(why); };
const onlyKeys = (o: Record<string, unknown>, allowed: string[], where: string) => { for (const k of Object.keys(o)) if (!allowed.includes(k)) no(`${where}: "${k}" is outside the studio subset`); };
const str = (v: unknown, where: string): string => (typeof v === "string" ? v : no(`${where} is not a string`));

// ---- reverse converters (JSON -> spec); anything they do not know throws NoFit and the file stays raw -----------
function text(v: unknown, where: string): DpText {
  let t = v;
  if (typeof t === "string" && /^\s*[{["]/.test(t)) { try { t = JSON.parse(t); } catch { no(`${where}: unreadable text`); } }
  if (typeof t === "string") return t || no(`${where}: empty text`);
  if (!isObj(t)) return no(`${where}: unsupported text`);
  onlyKeys(t, ["text", "color", "bold", "italic", "underlined", "strikethrough"], where);
  const s = str(t.text, `${where}.text`);
  const keys = Object.keys(t).filter((k) => k !== "text");
  if (!keys.length) return s;
  if (t.color !== undefined && !(TEXT_COLORS as readonly string[]).includes(String(t.color)) && !/^#[0-9a-fA-F]{6}$/.test(String(t.color))) no(`${where}: colour`);
  return t as DpText;
}
function ingredient(v: unknown, where: string): DpIngredient {
  const one = (x: unknown): string => (typeof x === "string" ? x : isObj(x) && typeof x.item === "string" && Object.keys(x).length === 1 ? x.item : isObj(x) && typeof x.tag === "string" && Object.keys(x).length === 1 ? `#${x.tag}` : no(`${where}: unsupported ingredient`));
  return Array.isArray(v) ? (v.length ? v.map(one) : no(`${where}: empty`)) : one(v);
}
function result(v: unknown, where: string): DpResult {
  if (!isObj(v)) return no(`${where}: unsupported result`);
  onlyKeys(v, ["id", "count", "components"], where);
  const r: DpResult = { item: str(v.id, `${where}.id`) };
  if (v.count !== undefined) r.count = typeof v.count === "number" ? v.count : no(`${where}.count`);
  if (v.components !== undefined) {
    if (!isObj(v.components)) no(`${where}.components`);
    const c = v.components as Record<string, unknown>;
    onlyKeys(c, ["minecraft:item_name", "minecraft:lore"], `${where}.components`);
    if (c["minecraft:item_name"] !== undefined) r.name = text(c["minecraft:item_name"], `${where}.item_name`);
    if (c["minecraft:lore"] !== undefined) r.lore = Array.isArray(c["minecraft:lore"]) ? c["minecraft:lore"].map((l, i) => text(l, `${where}.lore[${i}]`)) : no(`${where}.lore`);
  }
  return r;
}
const bare = (t: unknown) => String(t).replace(/^minecraft:/, "");
function recipe(j: Record<string, unknown>): Extract<DpResource, { type: "recipe" }>["recipe"] {
  const type = bare(j.type);
  const book = () => ({ ...(j.category !== undefined ? { category: str(j.category, "category") } : {}), ...(j.group !== undefined ? { group: str(j.group, "group") } : {}) }) as Record<string, string>;
  switch (type) {
    case "crafting_shaped": {
      onlyKeys(j, ["type", "category", "group", "pattern", "key", "result"], "recipe");
      if (!Array.isArray(j.pattern) || !isObj(j.key)) no("shaped recipe without pattern/key");
      const key: Record<string, DpIngredient> = {};
      for (const [k, x] of Object.entries(j.key as object)) key[k] = ingredient(x, `key.${k}`);
      return { kind: "shaped", ...book(), pattern: (j.pattern as unknown[]).map((p) => str(p, "pattern")), key, result: result(j.result, "result") } as never;
    }
    case "crafting_shapeless":
      onlyKeys(j, ["type", "category", "group", "ingredients", "result"], "recipe");
      return { kind: "shapeless", ...book(), ingredients: Array.isArray(j.ingredients) ? j.ingredients.map((x, i) => ingredient(x, `ingredients[${i}]`)) : no("ingredients"), result: result(j.result, "result") } as never;
    case "smelting": case "blasting": case "smoking": case "campfire_cooking":
      onlyKeys(j, ["type", "category", "group", "ingredient", "result", "experience", "cookingtime"], "recipe");
      return { kind: type, ...book(), ingredient: ingredient(j.ingredient, "ingredient"), result: result(j.result, "result"), ...(typeof j.experience === "number" ? { experience: j.experience } : {}), ...(typeof j.cookingtime === "number" ? { cookingTime: j.cookingtime } : {}) } as never;
    case "stonecutting":
      onlyKeys(j, ["type", "ingredient", "result"], "recipe");
      return { kind: "stonecutting", ingredient: ingredient(j.ingredient, "ingredient"), result: result(j.result, "result") };
    case "smithing_transform":
      onlyKeys(j, ["type", "template", "base", "addition", "result"], "recipe");
      return { kind: "smithing_transform", template: ingredient(j.template, "template"), base: ingredient(j.base, "base"), addition: ingredient(j.addition, "addition"), result: result(j.result, "result") };
    default: return no(`recipe type ${String(j.type)} is outside the studio subset`);
  }
}
function num(v: unknown, where: string): DpNum {
  if (typeof v === "number") return v;
  if (!isObj(v)) return no(`${where}: number provider`);
  const t = bare(v.type ?? "uniform");
  if (t === "constant" && typeof v.value === "number") return v.value;
  if (t === "uniform" && typeof v.min === "number" && typeof v.max === "number" && Object.keys(v).every((k) => ["type", "min", "max"].includes(k))) return { min: v.min, max: v.max };
  if (t === "binomial" && typeof v.n === "number" && typeof v.p === "number") return { n: v.n, p: v.p };
  return no(`${where}: number provider ${t}`);
}
function condition(c: unknown, where: string): DpCondition {
  if (!isObj(c)) return no(where);
  const t = bare(c.condition);
  if (t === "random_chance" && typeof c.chance === "number") { onlyKeys(c, ["condition", "chance"], where); return { cond: "random_chance", chance: c.chance }; }
  if (t === "killed_by_player") { onlyKeys(c, ["condition"], where); return { cond: "killed_by_player" }; }
  if (t === "survives_explosion") { onlyKeys(c, ["condition"], where); return { cond: "survives_explosion" }; }
  if (t === "match_tool" && isObj(c.predicate) && Object.keys(c.predicate).length === 1 && c.predicate.items !== undefined) {
    onlyKeys(c, ["condition", "predicate"], where);
    const it = c.predicate.items;
    return { cond: "match_tool", items: typeof it === "string" ? it : Array.isArray(it) ? it.map((x) => str(x, where)) : no(where) };
  }
  if (t === "weather_check") { onlyKeys(c, ["condition", "raining", "thundering"], where); return { cond: "weather", ...(typeof c.raining === "boolean" ? { raining: c.raining } : {}), ...(typeof c.thundering === "boolean" ? { thundering: c.thundering } : {}) }; }
  return no(`${where}: condition ${t} is outside the studio subset`);
}
const conds = (v: unknown, where: string) => (v === undefined ? {} : { conditions: Array.isArray(v) ? v.map((c, i) => condition(c, `${where}[${i}]`)) : no(where) });
function lootFn(f: unknown, where: string): DpFunction {
  if (!isObj(f)) return no(where);
