 * change keeps its original bytes. `rawEdits`: path -> new text for raw resources (validated with the file checks).
 * `version` decides pack.mcmeta and how edited resources are emitted. Nothing in `raw` is ever dropped.
 */
export function exportImported(imp: ImportedPack, edits: { spec?: DataPackSpec | null; rawEdits?: Record<string, string> }, ctx: { version: string; keepMcmeta?: Buffer | null }): ExportResult {
  const fe = dataPackFeatures(ctx.version);
  if (!fe.ok) return { ok: false, error: fe.error, specErrors: [] };
  const spec = edits.spec === undefined ? imp.spec : edits.spec;
  const out = new Map<string, Buffer>();
  const specErrors: string[] = [];
  if (spec && imp.namespace) {
    const unchanged = new Map(imp.converted.map((c) => [c.canonical, c]));
    const emitted = emitFiles(spec, imp.namespace, fe.features).filter((f) => f.path !== "pack.mcmeta");
