      if (!v.ok && /^nx_[a-z0-9]{8}$/.test(imp.namespace)) specErrors.push(...v.errors.map((e) => `${e.path}: ${e.message}`));
    }
    const byPath = new Map(emitted.map((f) => [f.path, f.text]));
