      if (orig) { out.set(orig.path, orig.original); byPath.delete(orig.path); }
    }
    for (const [p, t] of byPath) if (!out.has(p)) out.set(p, Buffer.from(t, "utf8"));
  }
  for (const r of imp.raw) out.set(r.path, edits.rawEdits?.[r.path] !== undefined ? Buffer.from(edits.rawEdits[r.path], "utf8") : r.bytes);
