  out.set("pack.mcmeta", Buffer.from(mcText, "utf8"));
  const files: PackFile[] = [...out].map(([path, b]) => ({ path, text: b.toString("utf8") })).sort((a, b) => (a.path < b.path ? -1 : 1));
  const report = validatePackFiles(files.filter((f) => !f.path.endsWith(".png") && !f.path.endsWith(".nbt")), ctx.version);
  const zip = writeZip([...out].map(([path, data]) => ({ path, data })));
  return { ok: true, files, zip, report, specErrors };
}

/** Validate ONE raw resource as text for a version (the editor's live check). */
export function checkRawResource(path: string, textValue: string, version: string): FileReport {
  return validatePackFiles([{ path: "pack.mcmeta", text: "{}" }, { path, text: textValue }].filter((f) => f.path !== "pack.mcmeta" || true), version);
}

