const TAG_REGISTRY: Record<string, "item" | "block" | "entity_type" | "function" | "enchantment"> = { "tags/item": "item", "tags/block": "block", "tags/entity_type": "entity_type", "tags/function": "function", "tags/enchantment": "enchantment" };

/** Read a data pack zip (bounded) and split it into a spec (what fits) and raw resources (everything else, kept). */
export function importDataPackZip(buf: Buffer, opts: { limits?: ZipLimits; namespace?: string } = {}): ImportResult {
  const zi = indexZip(buf, opts.limits ?? IMPORT_LIMITS);
  if (!zi.ok) return { ok: false, error: zi.error };
  const z = zi.zip;
  const issues: string[] = [...z.unsafeNames.map((n) => `unsafe entry name ignored: ${JSON.stringify(n).slice(0, 80)}`), ...z.duplicateNames.map((n) => `duplicate entry ignored: ${n}`)];
  const files: { path: string; bytes: Buffer }[] = [];
  for (const e of z.entries) {
    if (e.dir || z.unsafeNames.includes(e.name) || z.duplicateNames.includes(e.name)) continue;
    const r = readEntry(z, e);
    if (!r.ok) { issues.push(`${e.name}: ${r.error}`); continue; }
    files.push({ path: e.name, bytes: r.data });
  }
  // a pack zipped inside a folder ("mypack/pack.mcmeta"): strip that single top folder
  if (!files.some((f) => f.path === "pack.mcmeta")) {
    const tops = new Set(files.map((f) => f.path.split("/")[0]));
    if (tops.size === 1 && files.some((f) => f.path.endsWith("/pack.mcmeta") && f.path.split("/").length === 2)) { const top = [...tops][0] + "/"; for (const f of files) f.path = f.path.slice(top.length); }
  }
  const mc = files.find((f) => f.path === "pack.mcmeta");
  let description = "Imported data pack", packFormat: unknown = null;
  if (!mc) issues.push("pack.mcmeta is missing: Minecraft would not load this pack");
  else { try { const j = JSON.parse(mc.bytes.toString("utf8").replace(/^\uFEFF/, "")); if (isObj(j) && isObj(j.pack)) { packFormat = j.pack.min_format ?? j.pack.pack_format ?? null; if (typeof j.pack.description === "string") description = j.pack.description.slice(0, 200) || description; } } catch { issues.push("pack.mcmeta is not valid JSON"); } }

  // main namespace: the one with the most data files (minecraft excluded), unless the caller names it
  const counts = new Map<string, number>();
  for (const f of files) { const d = dataPath(f.path); if (d && d.ns !== "minecraft") counts.set(d.ns, (counts.get(d.ns) ?? 0) + 1); }
  const ns = opts.namespace ?? ([...counts].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1))[0]?.[0] ?? null);

  const resources: DpResource[] = [];
  const converted: ConvertedResource[] = [];
  const raw: RawResource[] = [];
