}

export type ExportResult = { ok: true; files: PackFile[]; zip: Buffer; report: FileReport; specErrors: string[] } | { ok: false; error: string; specErrors: string[] };

/**
 * Files of an imported pack after edits. `spec`: the (possibly edited) spec; a resource whose canonical form did not
 * change keeps its original bytes. `rawEdits`: path -> new text for raw resources (validated with the file checks).
 * `version` decides pack.mcmeta and how edited resources are emitted. Nothing in `raw` is ever dropped.
 */
export function exportImported(imp: ImportedPack, edits: { spec?: DataPackSpec | null; rawEdits?: Record<string, string> }, ctx: { version: string; keepMcmeta?: Buffer | null }): ExportResult {
  const fe = dataPackFeatures(ctx.version);
  if (!fe.ok) return { ok: false, error: fe.error, specErrors: [] };
  const spec = edits.spec === undefined ? imp.spec : edits.spec;
  const out = new Map<string, Buffer>();
  const specErrors: string[] = [];
  if (spec && imp.namespace) {
    const unchanged = new Map(imp.converted.map((c) => [c.canonical, c]));
    const emitted = emitFiles(spec, imp.namespace, fe.features).filter((f) => f.path !== "pack.mcmeta");
    // for validation of edited resources only (imported namespaces need not be nx_; references are checked by the file checks)
    if (spec !== imp.spec) {
      const v = validateDataPackSpec(spec, { version: ctx.version, namespace: /^nx_[a-z0-9]{8}$/.test(imp.namespace) ? imp.namespace : "nx_00000000" });
      if (!v.ok && /^nx_[a-z0-9]{8}$/.test(imp.namespace)) specErrors.push(...v.errors.map((e) => `${e.path}: ${e.message}`));
    }
    const byPath = new Map(emitted.map((f) => [f.path, f.text]));
    for (const r of spec.resources) {
      const orig = unchanged.get(canonicalJson(r));
      if (orig) { out.set(orig.path, orig.original); byPath.delete(orig.path); }
    }
    for (const [p, t] of byPath) if (!out.has(p)) out.set(p, Buffer.from(t, "utf8"));
  }
  for (const r of imp.raw) out.set(r.path, edits.rawEdits?.[r.path] !== undefined ? Buffer.from(edits.rawEdits[r.path], "utf8") : r.bytes);
  const mcText = ctx.keepMcmeta ? ctx.keepMcmeta.toString("utf8") : emitFiles({ schemaVersion: 1, name: "imported", description: imp.description || "Imported data pack", resources: [{ type: "function", id: "x", commands: ["#"] }] }, "nx_00000000", fe.features).find((f) => f.path === "pack.mcmeta")!.text;
  out.set("pack.mcmeta", Buffer.from(mcText, "utf8"));
  const files: PackFile[] = [...out].map(([path, b]) => ({ path, text: b.toString("utf8") })).sort((a, b) => (a.path < b.path ? -1 : 1));
  const report = validatePackFiles(files.filter((f) => !f.path.endsWith(".png") && !f.path.endsWith(".nbt")), ctx.version);
  const zip = writeZip([...out].map(([path, data]) => ({ path, data })));
  return { ok: true, files, zip, report, specErrors };
}

/** Validate ONE raw resource as text for a version (the editor's live check). */
export function checkRawResource(path: string, textValue: string, version: string): FileReport {
  return validatePackFiles([{ path: "pack.mcmeta", text: "{}" }, { path, text: textValue }].filter((f) => f.path !== "pack.mcmeta" || true), version);
}

