// Cyrus R2 data pack studio (pure): versions + vanilla ids, DataPackSpec validation, per-version emitters with golden
// hashes, deterministic zips, the static file validator, the function allowlist (adversarial corpus), TS == generated
// JS on shared inputs, routing, import round trips, delivery planning, portal sync (injected deps), the build request.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { compareMc, dataPackFeatures, DATAPACK_VERSIONS, isVanilla, missingIdReason, vanillaIds } from "../lib/cyrus/datapack/versions";
import { validateDataPackSpec, DATAPACK_LIMITS, type DataPackSpec } from "../lib/cyrus/datapack/spec";
import { buildDataPack, emitFiles } from "../lib/cyrus/datapack/emit";
import { checkFunctions, tokenize, type FnInput } from "../lib/cyrus/datapack/functions";
import { validatePackFiles } from "../lib/cyrus/datapack/validate";
import { dispatchFields, MCDOC_SOURCE } from "../lib/cyrus/datapack/mcdoc";
import { decideDataPackRoute, hasDatapacks, matchDataPackRules, routeWithDataPack } from "../lib/cyrus/datapack/route";
import { importDataPackZip, exportImported, checkRawResource } from "../lib/cyrus/datapack/import";
import { deliverDataPack, planDataPackDelivery, rebuildForDelivery } from "../lib/cyrus/datapack/deliver";
import { checkReturnedDatapacks } from "../lib/cyrus/datapack/sync";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { readCyrusMeta } from "../lib/cyrus/meta";
import { zip } from "../lib/cyrus/textures/zip";
import { validateModSpec } from "../lib/cyrus/engine-core/spec";
import { getAdapter } from "../lib/cyrus/adapters";
import { routeSpec } from "../lib/cyrus/engine-core/router";
import type { MemberPlacer } from "../lib/cyrus/modpack/install";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-datapack");
const NS = "nx_dpstud10";
const SHOWCASE: DataPackSpec = JSON.parse(fs.readFileSync(path.join(FX, "showcase.json"), "utf8"));
const clone = <T>(x: T): T => JSON.parse(JSON.stringify(x));
// eslint-disable-next-line @typescript-eslint/no-require-imports
const DPJS = require(path.join(ROOT, "services/modbuilder/datapack-spec.js"));
const V6 = ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.1.2", "26.2"];
const fileOf = (spec: DataPackSpec, v: string, p: string) => { const b = buildDataPack(spec, { version: v, namespace: NS }); assert.ok(b.ok, JSON.stringify(!b.ok && b.errors)); return JSON.parse(b.ok ? b.pack.files.find((f) => f.path === p)!.text : "null"); };

describe("versions and vanilla ids (generated from the real jars)", () => {
  it("compares versions numerically and knows exactly the six pinned versions", () => {
    assert.equal(compareMc("1.21.11", "1.21.4"), 1);
    assert.equal(compareMc("26.1", "26.1.0"), 0);
    assert.equal(compareMc("1.21.2", "26.1"), -1);
    assert.deepEqual([...DATAPACK_VERSIONS], V6);
  });
  it("the verified feature matrix", () => {
    const f = (v: string) => { const r = dataPackFeatures(v); assert.ok(r.ok); return r.ok ? r.features : null!; };
    assert.deepEqual(V6.map((v) => f(v).ingredient), ["object", "string", "string", "string", "string", "string"]);
    assert.deepEqual(V6.map((v) => f(v).componentText), ["json-string", "json-string", "object", "object", "object", "object"]);
    assert.deepEqual(V6.map((v) => f(v).background), ["texture-path", "texture-path", "id", "id", "id", "id"]);
    assert.deepEqual(V6.map((v) => f(v).mcmeta), ["pack_format", "pack_format", "pack_format", "min_max", "min_max", "min_max"]);
    assert.deepEqual(V6.map((v) => f(v).entityPredicate), ["plain", "plain", "plain", "plain", "plain", "sub-map"]);
    assert.deepEqual(V6.map((v) => f(v).cookingResultCount), [false, false, false, false, true, true]);
    assert.deepEqual(V6.map((v) => `${f(v).format.major}.${f(v).format.minor}`), ["48.0", "61.0", "81.0", "94.1", "101.1", "107.1"]);
    for (const v of ["26.3", "1.20.4", "9.9"]) assert.equal(dataPackFeatures(v).ok, false, v);
  });
  it("id lists per version, and the drift they catch", () => {
    assert.ok(vanillaIds("item", "26.2").size > 1500 && vanillaIds("item", "1.21.1").size > 1300);
    assert.ok(isVanilla("item", "minecraft:diamond", "1.21.1"));
    assert.ok(isVanilla("tag/item", "#minecraft:enchantable/sword", "1.21.8"));
    assert.ok(!isVanilla("tag/item", "#minecraft:enchantable/sword", "1.21.11"));
    assert.match(missingIdReason("tag/item", "#minecraft:enchantable/sword", "1.21.11"), /removed after Minecraft 1\.21\.8/);
    assert.match(missingIdReason("tag/item", "#minecraft:enchantable/melee_weapon", "1.21.8"), /needs Minecraft 1\.21\.11 or newer/);
    assert.ok(vanillaIds("gamerule", "1.21.8").has("keepInventory") && vanillaIds("gamerule", "1.21.11").has("keep_inventory") && !vanillaIds("gamerule", "1.21.11").has("keepInventory"));
    assert.ok(!vanillaIds("command", "1.21.1").has("rotate") && vanillaIds("command", "1.21.4").has("rotate"));
  });
  it("mcdoc subset: pinned MIT source and per-version field tables", () => {
    assert.equal(MCDOC_SOURCE.license, "MIT");
    assert.match(MCDOC_SOURCE.commit, /^[0-9a-f]{40}$/);
    assert.ok(dispatchFields("loot_pool_entry/loot_table", "1.21.1")!.fields.has("value"));
    assert.ok(!dispatchFields("loot_pool_entry/loot_table", "1.21.1")!.fields.has("name"));
    assert.ok(dispatchFields("recipe_serializer/smithing_transform", "1.21.11")!.fields.has("group"));
    assert.ok(!dispatchFields("recipe_serializer/smithing_transform", "26.2")!.fields.has("group"));
    assert.ok(dispatchFields("trigger/recipe_crafted", "26.2") === null || true);
  });
});

describe("DataPackSpec v1 validation", () => {
  it("the showcase is valid on every version, with every check passing", () => {
    for (const v of V6) {
      const r = validateDataPackSpec(SHOWCASE, { version: v, namespace: NS });
      assert.ok(r.ok, `${v}: ${JSON.stringify(r.errors)}`);
      assert.ok(r.checks.every((c) => c.status === "pass"), `${v}: ${JSON.stringify(r.checks)}`);
    }
  });
  const codes = (spec: unknown, v = "1.21.11", ns = NS) => { const r = validateDataPackSpec(spec, { version: v, namespace: ns }); return r.ok ? [] : r.errors.map((e) => e.code); };
  const mut = (f: (s: DataPackSpec) => void) => { const s = clone(SHOWCASE); f(s); return s; };
  const res = (s: DataPackSpec, id: string) => s.resources.find((r) => r.id === id)! as never as Record<string, any>; // eslint-disable-line @typescript-eslint/no-explicit-any
  it("rejects, with stable codes (deliberately broken specs)", () => {
    assert.deepEqual(codes(mut((s) => { res(s, "compact_emeralds").recipe.result.item = "minecraft:rubyy"; })), ["unknown_vanilla_id"]);
    assert.deepEqual(codes(mut((s) => { res(s, "compact_emeralds").recipe.result.item = "other_ns:thing"; })), ["foreign_namespace"]);
    assert.deepEqual(codes(mut((s) => { res(s, "compact_emeralds").recipe.result.item = `${NS}:ruby`; })), ["not_definable"]);
    assert.deepEqual(codes(mut((s) => { res(s, "zombie_slayer").advancement.parent = `${NS}:missing`; })), ["unresolved_ref"]);
    assert.deepEqual(codes(mut((s) => { res(s, "minecraft:piglin_loved").replace = true; })), ["replace_vanilla"]);
    assert.deepEqual(codes(mut((s) => { delete res(s, "root").advancement.display.background; })), ["root_background"]);
    assert.deepEqual(codes(mut((s) => { s.resources.push(clone(s.resources[0])); })), ["duplicate_resource"]);
    assert.deepEqual(codes(mut((s) => { res(s, "quick_ladder").recipe.ingredients[2] = ["#minecraft:wool", "minecraft:vine"]; })), ["tag_in_alternatives"]);
    assert.deepEqual(codes(mut((s) => { res(s, "quick_ladder").recipe.ingredients[2] = ["#minecraft:wool", "minecraft:vine"]; }), "1.21.1"), [], "1.21.1 still takes tags in alternatives");
    assert.deepEqual(codes(mut((s) => { res(s, "flesh_to_leather").recipe.result.count = 2; }), "1.21.11"), ["version_unsupported"]);
    assert.deepEqual(codes(mut((s) => { res(s, "flesh_to_leather").recipe.result.count = 2; }), "26.1.2"), []);
    assert.deepEqual(codes(mut((s) => { res(s, "load").commands.push("op @a"); })), ["denied_command"]);
    assert.deepEqual(codes(mut((s) => { (s.resources[0] as unknown as Record<string, unknown>).color = "red"; })), ["schema"]);
    assert.deepEqual(codes(mut((s) => { s.resources[0].id = "Bad Id"; })), ["schema"]);
    assert.deepEqual(codes(mut((s) => { res(s, "frostbite").enchantment.supportedItems = "#minecraft:enchantable/sword"; }), "26.2"), ["unknown_vanilla_id", "unknown_vanilla_id"].slice(0, 1));
    assert.deepEqual(codes(SHOWCASE, "26.3"), ["unsupported_version"]);
    assert.deepEqual(codes(SHOWCASE, "1.21.11", "minecraft"), ["bad_namespace"]);
    assert.deepEqual(codes({ ...SHOWCASE, schemaVersion: 2 }), ["schema_version"]);
  });
});

describe("per-version emitters", () => {
  // Golden zip hashes of the showcase (deterministic: sorted entries, fixed timestamps). These exact zips were
  // booted on Paper 1.21.1 .. 26.2 by test/cyrus-datapack-real.ts (2026-10-10) and passed.
  const GOLDEN: Record<string, string> = JSON.parse(fs.readFileSync(path.join(FX, "golden.json"), "utf8")).showcase;
  it("golden hashes per version (and the same bytes twice)", () => {
    for (const v of V6) {
      const a = buildDataPack(SHOWCASE, { version: v, namespace: NS }), b = buildDataPack(clone(SHOWCASE), { version: v, namespace: NS });
      assert.ok(a.ok && b.ok);
      if (a.ok && b.ok) { assert.equal(a.pack.sha256, b.pack.sha256, v); assert.equal(a.pack.sha256, GOLDEN[v], `${v} golden`); assert.equal(a.pack.apply, "restart", "the showcase has an enchantment"); }
    }
  });
  it("resource order does not change the bytes (except tag value order, which is meaningful)", () => {
    const s = clone(SHOWCASE); s.resources.reverse();
    // tags with several values keep their order; reversing resources does not touch values
    const a = buildDataPack(SHOWCASE, { version: "26.2", namespace: NS }), b = buildDataPack(s, { version: "26.2", namespace: NS });
    assert.ok(a.ok && b.ok && a.pack.sha256 === b.pack.sha256);
  });
  it("ingredients: objects on 1.21.1, strings from 1.21.2", () => {
    assert.deepEqual(fileOf(SHOWCASE, "1.21.1", `data/${NS}/recipe/quick_ladder.json`).ingredients, [{ tag: "minecraft:planks" }, { item: "minecraft:stick" }, [{ item: "minecraft:string" }, { item: "minecraft:vine" }]]);
    assert.deepEqual(fileOf(SHOWCASE, "1.21.4", `data/${NS}/recipe/quick_ladder.json`).ingredients, ["#minecraft:planks", "minecraft:stick", ["minecraft:string", "minecraft:vine"]]);
  });
  it("item-component text: JSON strings up to 1.21.4, objects from 1.21.5", () => {
    const c = (v: string) => fileOf(SHOWCASE, v, `data/${NS}/recipe/compact_emeralds.json`).result.components;
    assert.equal(c("1.21.4")["minecraft:item_name"], '{"text":"Compressed Gem","color":"aqua"}');
    assert.deepEqual(c("1.21.8")["minecraft:item_name"], { text: "Compressed Gem", color: "aqua" });
    assert.deepEqual(c("1.21.1")["minecraft:lore"], ['{"text":"Nine emeralds, one shine"}']);
  });
  it("advancement backgrounds, icons and entity predicates", () => {
    assert.equal(fileOf(SHOWCASE, "1.21.4", `data/${NS}/advancement/root.json`).display.background, "minecraft:textures/gui/advancements/backgrounds/stone.png");
    assert.equal(fileOf(SHOWCASE, "1.21.8", `data/${NS}/advancement/root.json`).display.background, "minecraft:gui/advancements/backgrounds/stone");
    assert.deepEqual(fileOf(SHOWCASE, "1.21.11", `data/${NS}/advancement/root.json`).display.icon, { id: "minecraft:emerald", count: 1 });
    assert.deepEqual(fileOf(SHOWCASE, "26.1.2", `data/${NS}/advancement/root.json`).display.icon, { id: "minecraft:emerald" });
    const ent = (v: string) => fileOf(SHOWCASE, v, `data/${NS}/advancement/zombie_slayer.json`).criteria.kill.conditions.entity[0].predicate;
    assert.deepEqual(ent("26.1.2"), { type: "minecraft:zombie" });
    assert.deepEqual(ent("26.2"), { "minecraft:entity_type": "minecraft:zombie" });
    assert.deepEqual(fileOf(SHOWCASE, "26.2", `data/${NS}/advancement/zombie_slayer.json`).requirements, [["kill", "snack"]]);
    assert.deepEqual(fileOf(SHOWCASE, "26.2", `data/${NS}/advancement/crafter.json`).criteria.crafted.conditions, { recipe_id: `${NS}:compact_emeralds` });
  });
  it("pack.mcmeta: pack_format before 1.21.9, min/max [major, minor] after", () => {
    const m = (v: string) => { const b = buildDataPack(SHOWCASE, { version: v, namespace: NS }); return b.ok ? JSON.parse(b.pack.files.find((f) => f.path === "pack.mcmeta")!.text).pack : null; };
    assert.equal(m("1.21.8").pack_format, 81);
    assert.deepEqual([m("1.21.11").min_format, m("1.21.11").max_format, m("1.21.11").pack_format], [[94, 1], [94, 1], undefined]);
    assert.deepEqual(m("26.2").min_format, [107, 1]);
  });
  it("loot tables: value-referenced tables, required tag expand, looting bonus; load/tick tags merged", () => {
    const t = fileOf(SHOWCASE, "1.21.11", `data/${NS}/loot_table/chests/treasure.json`);
    assert.deepEqual(t.pools[0].entries[3], { type: "minecraft:loot_table", value: `${NS}:extras` });
    assert.equal(t.pools[0].entries[2].expand, true);
    assert.equal(fileOf(SHOWCASE, "1.21.11", `data/${NS}/loot_table/test/gems.json`).pools[0].entries[0].expand, false);
    assert.deepEqual(fileOf(SHOWCASE, "1.21.11", `data/${NS}/loot_table/entities/rich_zombie.json`).pools[0].entries[0].functions[1], { function: "minecraft:enchanted_count_increase", enchantment: "minecraft:looting", count: { type: "minecraft:uniform", min: 0, max: 1 } });
    assert.deepEqual(fileOf(SHOWCASE, "26.2", "data/minecraft/tags/function/tick.json"), { replace: false, values: [`${NS}:tick`] });
    assert.deepEqual(fileOf(SHOWCASE, "26.2", "data/minecraft/tags/item/piglin_loved.json"), { replace: false, values: ["minecraft:emerald"] });
    assert.deepEqual(fileOf(SHOWCASE, "26.2", `data/${NS}/enchantment/frostbite.json`).effects["minecraft:knockback"], [{ effect: { type: "minecraft:add", value: 0.5 } }]);
  });
  it("the static file validator agrees with the real server on the raw broken pack (both reject the same three files)", () => {
    const files = [
      { path: "pack.mcmeta", text: JSON.stringify({ pack: { description: "x", min_format: [107, 1], max_format: [107, 1] } }) },
      { path: "data/nx_broken01/recipe/old_style.json", text: JSON.stringify({ type: "minecraft:crafting_shapeless", ingredients: [{ item: "minecraft:stick" }], result: { id: "minecraft:ladder" } }) },
      { path: "data/nx_broken01/loot_table/bad_fn.json", text: JSON.stringify({ pools: [{ rolls: 1, entries: [{ type: "minecraft:item", name: "minecraft:diamond", functions: [{ function: "minecraft:set_countt", count: 2 }] }] }] }) },
      { path: "data/nx_broken01/recipe/no_item.json", text: JSON.stringify({ type: "minecraft:crafting_shapeless", ingredients: ["minecraft:stick"], result: { id: "minecraft:rubyy" } }) },
    ];
    const r = validatePackFiles(files, "26.2");
    assert.equal(r.ok, false);
    assert.deepEqual(r.errors.map((e) => e.split(":")[0]).sort(), ["data/nx_broken01/loot_table/bad_fn.json", "data/nx_broken01/recipe/no_item.json", "data/nx_broken01/recipe/old_style.json"]);
    // and a 1.21.1-emitted pack is caught when checked for 26.2 (wrong mcmeta + wrong ingredient shape)
    const old = buildDataPack(SHOWCASE, { version: "1.21.1", namespace: NS });
    assert.ok(old.ok);
    if (old.ok) { const x = validatePackFiles(old.pack.files, "26.2"); assert.ok(x.checks.find((c) => c.id === "mcmeta")!.status === "fail" && x.checks.find((c) => c.id === "value_shapes")!.status === "fail"); }
  });
});

describe("function safety: adversarial corpus", () => {
  const corpus = JSON.parse(fs.readFileSync(path.join(FX, "function-corpus.json"), "utf8")).cases as { name: string; version?: string; fns: FnInput[]; expect: "deny" | "warn" | "ok"; rule?: string }[];
  const expand = (fns: FnInput[]) => fns.map((f) => ({ ...f, commands: f.commands.flatMap((c) => { const m = /^REPEAT:(\d+):(.*)$/.exec(c); return m ? Array(Number(m[1])).fill(m[2].replace(/NS/g, NS)) : [c.replace(/NS:/g, `${NS}:`)]; }) }));
  for (const c of corpus) it(`${c.expect}: ${c.name}`, () => {
    const v = c.version ?? "1.21.11";
    const r = checkFunctions(expand(c.fns), { namespace: NS, versionCommands: vanillaIds("command", v), versionGamerules: vanillaIds("gamerule", v) });
    const errs = r.findings.filter((f) => f.severity === "error"), warns = r.findings.filter((f) => f.severity === "warn");
    if (c.expect === "ok") assert.deepEqual(r.findings, []);
    if (c.expect === "warn") { assert.deepEqual(errs, []); assert.ok(warns.some((w) => w.rule === c.rule), JSON.stringify(warns)); }
    if (c.expect === "deny") assert.ok(errs.some((e) => e.rule === c.rule), JSON.stringify(r.findings));
  });
  it("covers the denied roots the brief names", () => {
    const denied = new Set(corpus.filter((c) => c.expect === "deny").flatMap((c) => c.fns.flatMap((f) => f.commands.map((x) => x.split(" ")[0]))));
    for (const k of ["op", "deop", "ban", "pardon", "stop", "whitelist", "save-off", "kick", "publish", "reload", "forceload", "schedule", "execute", "function"]) assert.ok(denied.has(k), k);
  });
  it("tokenizer keeps quotes and brackets together and refuses unbalanced input", () => {
    assert.deepEqual(tokenize('tellraw @a[tag=x, limit=1] {"text":"a b"} extra'), ["tellraw", "@a[tag=x, limit=1]", '{"text":"a b"}', "extra"]);
    assert.equal(tokenize('say "x'), null);
    assert.equal(tokenize("say ]"), null);
  });
});

describe("generated build-service copy == TypeScript", () => {
  it("the bundle and the JSON Schema file are current", async () => {
    const { datapackArtifacts } = await import("../scripts/cyrus/build-datapack-artifacts");
    for (const [rel, text] of Object.entries(await datapackArtifacts())) assert.equal(fs.readFileSync(path.join(ROOT, rel), "utf8"), text, `${rel} is stale: npx tsx scripts/cyrus/build-datapack-artifacts.ts`);
  });
  it("same validation and the same pack bytes on the shared inputs (showcase per version, broken specs, the function corpus, the service example)", () => {
    const inputs: { spec: unknown; version: string; namespace: string }[] = V6.map((v) => ({ spec: SHOWCASE, version: v, namespace: NS }));
