    assert.equal(P.systemPrompt("1.21.11", { textures: true }), P.systemPrompt("1.21.11", { textures: true, datapack: false }), "texture builds byte-identical");
    assert.match(P.DATAPACK_SECTION, new RegExp(`At most ${DATAPACK_LIMITS.maxFiles} files`));
    for (const v of V6) assert.ok(validateDataPackSpec(JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/datapack-example.json"), "utf8")), { version: v, namespace: "nx_abcd1234" }).ok, v);
