    assert.ok(ex.ok);
    if (!ex.ok) return;
    assert.deepEqual(ex.files.map((f) => [f.path, f.text]), pack.files.map((f) => [f.path, f.text]));
    assert.ok(ex.report.ok, JSON.stringify(ex.report.errors));
  });
  it("the converted spec re-emits to the same JSON for every resource it holds", () => {
    const imp = importDataPackZip(pack.zip);
    if (!imp.ok || !imp.spec) return assert.fail("import failed");
    const fe = dataPackFeatures("1.21.4");
    if (!fe.ok) return assert.fail();
    const again = new Map(emitFiles(imp.spec, NS, fe.features).map((f) => [f.path, f.text]));
    for (const f of pack.files) if (again.has(f.path) && f.path !== "pack.mcmeta") assert.equal(again.get(f.path), f.text, f.path);
  });
  it("third-party pack: worldgen, predicates, structures, vanilla overrides and pack.png are kept untouched; edits are validated", () => {
    const files = [
      { path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: 61, description: "Cool Pack" } })) },
      { path: "pack.png", data: Buffer.from([0x89, 0x50, 0x4e, 0x47, 0, 1, 2, 3]) },
      { path: "data/coolpack/recipe/torch.json", data: Buffer.from(JSON.stringify({ type: "minecraft:crafting_shapeless", ingredients: ["minecraft:coal", "minecraft:stick"], result: { id: "minecraft:torch", count: 8 } })) },
      { path: "data/coolpack/recipe/fancy.json", data: Buffer.from(JSON.stringify({ type: "minecraft:crafting_transmute", input: "minecraft:shulker_box", material: "minecraft:blue_dye", result: "minecraft:blue_shulker_box" })) },
      { path: "data/coolpack/worldgen/biome/glow.json", data: Buffer.from("{\"temperature\":0.5}") },
      { path: "data/coolpack/predicate/night.json", data: Buffer.from("{\"condition\":\"minecraft:time_check\",\"value\":{\"min\":13000,\"max\":23000}}") },
      { path: "data/coolpack/structure/hut.nbt", data: Buffer.from([0x1f, 0x8b, 8, 0, 1, 2]) },
      { path: "data/minecraft/loot_table/entities/zombie.json", data: Buffer.from("{\"pools\":[]}") },
      { path: "data/minecraft/tags/item/planks.json", data: Buffer.from("{\"values\":[\"minecraft:bamboo_block\"]}") },
      { path: "data/coolpack/function/hi.mcfunction", data: Buffer.from("say hi\n$say $(x)\n") },
    ];
    const imp = importDataPackZip(zip(files));
    assert.ok(imp.ok);
    if (!imp.ok) return;
    assert.equal(imp.namespace, "coolpack");
    assert.deepEqual(imp.spec!.resources.map((r) => `${r.type}:${r.id}`).sort(), ["function:hi", "recipe:torch", "tag:minecraft:planks"]);
    assert.deepEqual(imp.raw.map((r) => r.path).sort(), ["data/coolpack/predicate/night.json", "data/coolpack/recipe/fancy.json", "data/coolpack/structure/hut.nbt", "data/coolpack/worldgen/biome/glow.json", "data/minecraft/loot_table/entities/zombie.json", "pack.png"]);
    assert.match(imp.raw.find((r) => r.path.endsWith("zombie.json"))!.reason, /vanilla/);
    const ex = exportImported(imp, {}, { version: "1.21.4" });
    assert.ok(ex.ok);
    if (!ex.ok) return;
    const byPath = new Map(ex.files.map((f) => [f.path, f.text]));
    for (const f of files) assert.equal(byPath.get(f.path), f.data.toString("utf8"), f.path);
    assert.ok(ex.report.checks.find((c) => c.id === "function_safety")!.status === "fail", "the macro line in the imported function is reported");
    // edit a converted recipe: re-emitted for the version; edit a raw file: validated
    const spec = clone(imp.spec!);
    (spec.resources.find((r) => r.id === "torch") as { recipe: { result: { count: number } } }).recipe.result.count = 4;
    const ex2 = exportImported(imp, { spec, rawEdits: { "data/coolpack/predicate/night.json": "{\"condition\":\"minecraft:time_check\",\"value\":13000}" } }, { version: "1.21.4" });
    assert.ok(ex2.ok);
    if (ex2.ok) {
      assert.deepEqual(JSON.parse(ex2.files.find((f) => f.path === "data/coolpack/recipe/torch.json")!.text).result, { id: "minecraft:torch", count: 4 });
      assert.equal(ex2.files.find((f) => f.path === "data/coolpack/predicate/night.json")!.text, "{\"condition\":\"minecraft:time_check\",\"value\":13000}");
      assert.equal(ex2.files.find((f) => f.path === "pack.png")!.text, files[1].data.toString("utf8"));
    }
    assert.equal(checkRawResource("data/coolpack/recipe/x.json", JSON.stringify({ type: "minecraft:crafting_shapeless", ingredients: [{ item: "minecraft:stick" }], result: { id: "minecraft:ladder" } }), "1.21.4").ok, false);
    assert.equal(checkRawResource("data/coolpack/recipe/x.json", JSON.stringify({ type: "minecraft:crafting_shapeless", ingredients: ["minecraft:stick"], result: { id: "minecraft:ladder" } }), "1.21.4").ok, true);
  });
  it("hostile zips: unsafe names and junk are reported, never extracted; a non-zip is refused", () => {
    const evil = zip([{ path: "pack.mcmeta", data: Buffer.from("{\"pack\":{\"pack_format\":61,\"description\":\"e\"}}") }, { path: "../../etc/passwd", data: Buffer.from("x") }, { path: "data/e/recipe/bad.json", data: Buffer.from("{not json") }]);
    const imp = importDataPackZip(evil);
    assert.ok(imp.ok);
    if (imp.ok) {
      assert.ok(imp.issues.some((i) => /unsafe entry name/.test(i)));
      assert.ok(!imp.raw.some((r) => r.path.includes("..")));
      assert.ok(imp.raw.some((r) => r.path === "data/e/recipe/bad.json" && /not valid JSON/.test(r.reason)));
    }
    assert.equal(importDataPackZip(Buffer.from("not a zip at all")).ok, false);
  });
});

describe("delivery (planned, flag-gated) and portal sync", () => {
  const b = buildDataPack(SHOWCASE, { version: "26.2", namespace: NS });
  assert.ok(b.ok);
  const pack = b.ok ? b.pack : null!;
  const memPlacer = (): MemberPlacer & { placed: string[] } => { const placed: string[] = []; return { placed, statePaths: [], async place({ files }) { for (const f of files) placed.push(f.target); }, async remove() {} }; };
  it("plan: one file per pack in <level>/datapacks, minecraft:reload for reloadable content, restart for enchantments", () => {
    assert.deepEqual(planDataPackDelivery({ namespace: NS, name: "loot", apply: "reload" }).commands, ["minecraft:reload"]);
    const p = planDataPackDelivery({ namespace: NS, name: "showcase", apply: "restart" });
    assert.equal(p.relPath, `datapacks/nxeon-${NS}-showcase.zip`);
    assert.deepEqual(p.commands, []);
  });
  it("OFF by default: nothing is placed; ON: placed through the installer, reload sent, restart reported", async () => {
    const placer = memPlacer();
    const input = { projectId: "cp1", revisionId: "rv1", namespace: NS, name: pack.name, version: "26.2", zip: pack.zip, sha256: pack.sha256, apply: pack.apply };
    const off = await deliverDataPack(input, { placer, env: {} });
    assert.equal(off.ok, false); assert.deepEqual(placer.placed, []);
    const sent: string[] = [];
    const on = await deliverDataPack({ ...input, apply: "reload" }, { placer, env: { CYRUS_DATAPACK_DELIVERY_REAL: "1" }, base: "/opt/mc", level: "world", runConsole: async (c) => { sent.push(c); } });
    assert.ok(on.ok);
    assert.deepEqual(placer.placed, [`/opt/mc/world/datapacks/nxeon-${NS}-showcase.zip`]);
    assert.deepEqual(sent, ["minecraft:reload"]);
    const rs = await deliverDataPack(input, { placer: memPlacer(), env: { CYRUS_DATAPACK_DELIVERY_REAL: "1" }, runConsole: async (c) => { sent.push(c); } });
    assert.ok(rs.ok && rs.restartRequired);
    const disabled = await deliverDataPack(input, { placer: { ...memPlacer(), disabledReason: "engine off" }, env: { CYRUS_DATAPACK_DELIVERY_REAL: "1" } });
    assert.deepEqual(disabled, { ok: false, skipped: true, reason: "engine off" });
  });
  it("rebuildForDelivery: same spec + version = same bytes; a changed hash is refused", () => {
    const ok = rebuildForDelivery({ spec: SHOWCASE, version: "26.2", packSha256: pack.sha256 }, NS);
    assert.ok(ok.ok && ok.zip.equals(pack.zip));
    assert.equal(rebuildForDelivery({ spec: SHOWCASE, version: "26.2", packSha256: "0".repeat(64) }, NS).ok, false);
  });
  it("checkReturnedDatapacks re-validates, drops failures and cross-pack duplicates", () => {
    const bad = clone(SHOWCASE); bad.name = "bad"; (bad.resources[0] as { recipe: { result: { item: string } } }).recipe.result.item = "minecraft:nope";
    const dup = clone(SHOWCASE); dup.name = "dup";
    const r = checkReturnedDatapacks([{ name: "showcase", path: "assets/datapack/showcase.json", sha256: "x", spec: SHOWCASE, pack: { sha256: pack.sha256 } }, { name: "bad", path: "", sha256: "", spec: bad }, { name: "dup", path: "", sha256: "", spec: dup }], { namespace: NS, mcVersion: "26.2" });
    assert.deepEqual(r.ok.map((x) => x.name), ["showcase"]);
    assert.ok(r.ok[0].serviceAgreed);
    assert.deepEqual(r.dropped.map((d) => d.name), ["bad", "dup"]);
  });
  it("syncBuildAssets: a data-pack-only build records one revision (dataPack + asset roles) and one datapack asset; re-sync is idempotent", async () => {
    const revs: { id: string; modBuildId: string; input: unknown }[] = [], assets: unknown[] = [];
    const deps: AssetSyncDeps = {
      selectStore: () => ({ ok: false, reason: "off" }) as never,
      projectForRootBuild: async () => ({ id: "cp1", namespace: NS, userId: "u" }), createProject: async () => { throw new Error("no"); },
      findRevisionForBuild: async (_p, m) => revs.find((r) => r.modBuildId === m) ?? null, headRevisionId: async () => revs.at(-1)?.id ?? null,
      addRevision: async (_p, input) => { const r = { id: `rv${revs.length + 1}`, modBuildId: input.modBuildId!, input }; revs.push(r); return r; },
      recordAsset: async (_p, a) => { if (!assets.some((x) => JSON.stringify(x) === JSON.stringify(a))) assets.push(a); return a; },
    };
    const ar = { namespace: NS, promptVersion: null, qualityVersion: "tq-1", kept: false, textures: [], downgraded: [], warnings: [], datapacks: [{ name: "showcase", path: "assets/datapack/showcase.json", sha256: pack.specSha256, spec: SHOWCASE, pack: { sha256: pack.sha256 } }], datapackPromptVersion: "mb-datapack-2026-10-10.1" };
    const build = { id: "mb1", userId: "u", rootBuildId: null, mcVersion: "26.2", pluginName: "Show", jarName: "Show.jar", jarSha256: "a".repeat(64) };
    const out = await syncBuildAssets(build, ar, deps);
    assert.equal(revs.length, 1);
    const m = (revs[0].input as { manifest: { path: string; role: string }[] }).manifest;
    assert.deepEqual(m.map((x) => `${x.role}:${x.path}`), ["artifact:plugin/Show.jar", "asset:assets/datapack/showcase.json", "dataPack:datapack/showcase-26.2.zip"]);
    assert.equal((revs[0].input as { engine: { promptVersion: string } }).engine.promptVersion, "mb-datapack-2026-10-10.1");
    assert.equal(assets.length, 1);
    assert.equal((assets[0] as { kind: string }).kind, "datapack");
    assert.equal((assets[0] as { provenance: { packSha256: string } }).provenance.packSha256, pack.sha256);
    assert.deepEqual(out!.datapacks!.map((d) => [d.name, d.sha256, d.apply]), [["showcase", pack.sha256, "restart"]]);
    assert.equal(out!.pack, null, "no resource pack for a data-pack-only build");
    await syncBuildAssets(build, ar, deps);
    assert.equal(revs.length, 1, "idempotent");
    assert.equal(assets.length, 1);
  });
});

