import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";

/**
 * Cyrus R2 data pack studio against a THROWAWAY Postgres: the build request with the real deps (a FREE account with
 * no plan gets the data pack route and a reserved-namespace project: data packs are not plan-gated), and the portal
 * sync with the real engine-core store: one revision with the dataPack manifest role, one content-addressed
 * CyrusProjectAsset of kind "datapack", idempotent on re-sync and under concurrent first syncs; the stored asset
 * rebuilds to the same zip for delivery. No server, no model, no network.
 *
 * Opt-in and fail-closed: runs only when CYRUS_DATAPACK_DB_TEST=1 and DATABASE_URL is a node-2 agent database.
 *   devhost db push && devhost run --lock -- env CYRUS_DATAPACK_DB_TEST=1 npx tsx --test test/cyrus-datapack-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_DATAPACK_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_DATAPACK_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const uid = (n: string) => `cydp-${uniq}-${n}`;
const SHOWCASE = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures/cyrus-datapack/showcase.json"), "utf8"));

before(async () => { if (safe) db = (await import("../lib/db.ts")).db; });
after(async () => {
  if (!safe) return;
  const ids = (await db.cyrusProject.findMany({ where: { userId: { startsWith: `cydp-${uniq}-` } }, select: { id: true } })).map((p) => p.id);
  await db.cyrusProjectAsset.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusRevision.deleteMany({ where: { projectId: { in: ids } } });
  await db.cyrusProject.deleteMany({ where: { id: { in: ids } } });
  await db.$disconnect();
});

describe("Cyrus data pack studio (throwaway DB)", { skip }, () => {
  it("build request: a free account gets the data pack route (not plan-gated) with a real reserved namespace; off = nothing", async () => {
    const { resolveBuildAssets } = await import("../lib/cyrus/assets/request.ts");
    const { assetRequestDeps } = await import("../lib/modbuilder/create.ts");
    const root = `mb${uniq}free`.slice(0, 40);
    const off = await resolveBuildAssets({ userId: uid("free"), rootBuildId: root, change: false, text: "custom crafting recipes and chest loot tables", mcVersion: "1.21.11" }, { ...assetRequestDeps, dataPackStudioOn: () => false });
    assert.deepEqual(off, { plan: null, service: null, meta: null });
    assert.equal(await db.cyrusProject.count({ where: { userId: uid("free") } }), 0, "off: no project created");
    const on = await resolveBuildAssets({ userId: uid("free"), rootBuildId: root, change: false, text: "custom crafting recipes and chest loot tables", mcVersion: "1.21.11" }, { ...assetRequestDeps, dataPackStudioOn: () => true });
    assert.equal(on.service?.datapack, true, JSON.stringify(on.meta));
    assert.equal(on.service?.texture, false);
    assert.match(on.service!.namespace, /^nx_[a-z0-9]{8}$/);
    assert.deepEqual(on.meta!.datapack!.matched.sort(), ["datapack_loot", "datapack_recipe"]);
    const p = await db.cyrusProject.findFirst({ where: { userId: uid("free") } });
    assert.equal(p?.namespace, on.service!.namespace);
  });

  it("portal sync: one revision + one datapack asset, idempotent (re-sync and 3 concurrent first syncs), and the asset rebuilds to the same zip", async () => {
    const { syncBuildAssets } = await import("../lib/cyrus/assets/sync.ts");
    const { defaultAssetSyncDeps } = await import("../lib/cyrus/assets/sync-deps.ts");
    const { createProject } = await import("../lib/cyrus/engine-core/store.ts");
    const { buildDataPack } = await import("../lib/cyrus/datapack/emit/index.ts");
    const { rebuildForDelivery } = await import("../lib/cyrus/datapack/deliver.ts");
    const root = `mb${uniq}sync`.slice(0, 40);
    const project = await createProject({ userId: uid("sync"), game: "minecraft", rootBuildId: root });
    const ns = project.namespace;
    const spec = JSON.parse(JSON.stringify(SHOWCASE).replaceAll("nx_dpstud10", ns));
    const built = buildDataPack(spec, { version: "26.2", namespace: ns });
    assert.ok(built.ok);
    if (!built.ok) return;
    const deps = defaultAssetSyncDeps({});
    const ar = { namespace: ns, promptVersion: null, qualityVersion: "tq-1", kept: false, textures: [], downgraded: [], warnings: [], datapacks: [{ name: "showcase", path: "assets/datapack/showcase.json", sha256: built.pack.specSha256, spec, pack: { sha256: built.pack.sha256 } }], datapackPromptVersion: "mb-datapack-2026-10-10.1" };
    const build = (id: string) => ({ id, userId: uid("sync"), rootBuildId: root, mcVersion: "26.2", pluginName: "Showcase", jarName: "Showcase-1.0.0.jar", jarSha256: "b".repeat(64) });
    const first = await syncBuildAssets(build(root), ar, deps);
    assert.deepEqual(first!.datapacks!.map((d) => d.sha256), [built.pack.sha256]);
    await syncBuildAssets(build(root), ar, deps);
    const revs = await db.cyrusRevision.findMany({ where: { projectId: project.id } });
    assert.equal(revs.length, 1);
    const manifest = revs[0].manifest as { path: string; role: string; sha256: string }[];
    assert.ok(manifest.some((m) => m.role === "dataPack" && m.path === "datapack/showcase-26.2.zip" && m.sha256 === built.pack.sha256), JSON.stringify(manifest));
    assert.equal(revs[0].status, "passed");
    const assets = await db.cyrusProjectAsset.findMany({ where: { projectId: project.id } });
    assert.equal(assets.length, 1);
    assert.equal(assets[0].kind, "datapack");
    assert.equal(assets[0].mime, "application/vnd.nxeon.datapack-spec+json");
    const again = rebuildForDelivery(assets[0].provenance as { spec: unknown; version: string; packSha256: string }, ns);
    assert.ok(again.ok && again.zip.equals(built.pack.zip), "the stored spec rebuilds the exact zip");
    // concurrent first syncs of a second build in the chain
    const second = `${root}b`.slice(0, 41);
    await Promise.all([1, 2, 3].map(() => syncBuildAssets(build(second), ar, deps)));
    assert.equal(await db.cyrusRevision.count({ where: { projectId: project.id, modBuildId: second } }), 1);
    assert.equal(await db.cyrusProjectAsset.count({ where: { projectId: project.id } }), 1, "content addressed: the same spec is one row");
  });
});

